import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea, Select, SelectItem } from "@heroui/react";
import { FileUploader, Loading } from '../../components';
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";
import makeAnimated from "react-select/animated"
import CreateSelect from "react-select/creatable";
import { useDispatch, useSelector } from "react-redux";
import { resetRedux, uploadUserDocuments } from "../../redux/users/users/actions";
import { getLoggedInUser } from "../../helpers/authUtils";
import documentTypes from "../../data/documentTypes";



export default function DocumentUploadModal({ openModal, setopenModal, item, updated, setUpdated, modalTitle }) {
    const animatedComponent = makeAnimated();
    const loading = useSelector((state) => state.Users.loading);
    const profile = useSelector((state) => state.Users.user);
    const response_code = useSelector((state) => state.Users.response_code);
    const response_message = useSelector((state) => state.Users.response_message);
    const errors = useSelector((state) => state.Users.errors);
    const [user, setUser] = useState()
    const dispatch = useDispatch()

    useEffect(() => { setUser(getLoggedInUser()) }, [])
    useEffect(() => {
        dispatch(resetRedux())
    }, [])
    useEffect(() => {

        if (profile) {
            console.log("response code", response_code)

            // setopenModal(false)
            // dispatch(resetRedux())
        }
    }, [profile])

    const formik = useFormik({
        initialValues: {
            documents: [],
            document_number: "",
            document_type: ""
        },

        validationSchema: Yup.object({

            document_number: Yup.string()
                .min(3, "Must be 15 characters or more")
                .required("National ID card number is required"),
            document_type: Yup.object()
                .required("Document type is required"),
            documents: Yup.array().label('KYC documents').min(2, 'Images of both sides of national ID required').max(5, 'Not more than 5 images permmited'),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log(values)


            let data = new FormData();

            data.append("document_type", values.document_type.value);
            data.append("document_number", values.document_number);
            values.documents.map((x) => {
                data.append("documents", x);
            });




            if (user) {
                dispatch(uploadUserDocuments
                    (data, user.id))
            }


            resetForm()
        },
    });


    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    useEffect(() => {
        if (response_message) {
            setopenModal(false)
            toast.success(response_message

            );
            dispatch(resetRedux())
        }

    }, [response_message]);


    const handleRemoveSelectedImage = (file) => {
        console.log("file", file);
        // formik.values.documents.filter((x) => x.preview !== file.preview);

        formik.setFieldValue(
            "documents",
            formik.values.documents.filter((x) => x.preview !== file.preview)
        );
    };

    return (
        <>
            <Modal
                isOpen={openModal}
                placement="top"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            {loading ? <Loading /> : <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1 items-center">{modalTitle}</ModalHeader>
                                <ModalBody>
                                    <div className="grid grid-cols-1">
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="document_type"
                                            key="document_type"
                                            name="document_type"
                                            components={animatedComponent}
                                            placeholder="Select document type"
                                            isClearable
                                            value={formik.values.category}
                                            onChange={(value) => formik.setFieldValue("document_type", value)}
                                            options={documentTypes}
                                        />
                                        {formik.touched.document_type && formik.errors.document_type ? (
                                            <p className="text-red-500 text-xs">{formik.errors.document_type}</p>
                                        ) : null}
                                    </div>

                                    <Input
                                        id="document_number"
                                        name="document_number"
                                        autoFocus
                                        label="National ID Number"
                                        placeholder="Enter national ID card number"
                                        variant="bordered"
                                        type="text"
                                        color={formik.errors.document_number ? "danger" : "grey"}
                                        errorMessage={formik.errors.document_number}
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.document_number}
                                        value={formik.values.document_number}
                                    />


                                    <div className="bg-white">
                                        <FileUploader
                                            placeholder="Select profile pictures"
                                            formik={formik}
                                            name="documents"

                                            types=".png,.jpg,.jpeg"
                                            value={formik.values.documents}
                                            accept={{
                                                "image/png": [".png"],
                                                "image/jpeg": [".jpeg"],
                                            }}
                                        />
                                        {formik.errors.documents ? (
                                            <p className="text-red-500 text-xs">{formik.errors.documents}</p>
                                        ) : null}
                                        {formik.values.documents && formik.values.documents.length > 0 && (
                                            <div className="shadow-md rounded my-5 bg-zinc-100 p-5">
                                                <h2 className="text-center font-bold mb-5">
                                                    Images selected for upload
                                                </h2>
                                                <div className="container flex flex-wrap mx-auto">
                                                    <div className="grid grid-cols-4 gap-2 sm:grid-cols-4 gap-3">
                                                        {formik.values.documents?.map((file) => (
                                                            <div
                                                                className="md:shrink-0 rounded "
                                                                key={file.preview}
                                                            >
                                                                <button
                                                                    onClick={() => handleRemoveSelectedImage(file)}
                                                                    className="flex  absolute text-red-500 border-red-500 border text-lg  font-bold"
                                                                >
                                                                    x
                                                                </button>
                                                                <img
                                                                    className="h-10 w-full object-cover md:h-full md:w-48 shadow-md"
                                                                    src={file.preview}
                                                                    alt=""
                                                                />
                                                            </div>
                                                        ))}
                                                    </div>

                                                </div>

                                            </div>
                                        )}
                                    </div>


                                </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>}


                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
