import React, { useEffect, useState } from 'react'
import GenericsTable from './GenericsTable'

import useApi from '../../hooks/useApi'
import { useNavigate, } from 'react-router-dom';
import GenericsFormModal from './GenericsFormModal';
import genericsApi from '../../api/drugs/genericsApi';
import { Loading } from '../../components';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Drug class", uid: "drug_class_title" },
    { name: "Drug sub class", uid: "drug_sub_class_title" },
    { name: "Description", uid: "description" },
    { name: "Actions", uid: "actions" },
];


function GenericsList() {
    const [openEditModal, setopenEditModal] = useState(false)

    const navigate = useNavigate()
    const [generic, setGeneric] = useState()
    const [generics, setGenerics] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const genericsActionsApi = useApi(genericsApi.genericsAction)
    const [rowsPerPage, setRowsPerPage] = React.useState(20);

    const getGenerics = async () => {
        await genericsActionsApi.request({
            "action": "GetGenerics"

        })
    }


    useEffect(() => {
        getGenerics()
    }, [])


    const handleEditAction = (item) => {
        setUpdated(false)
        setopenEditModal(true)
        setGeneric(item)
        setmodalTitle(`Edit ${item.title}`)

    }

    const handleAddAction = () => {
        setUpdated(false)
        setopenEditModal(true)
        setmodalTitle("Add generic drug")
        setGeneric(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/systems/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {

        navigate(`/systems/delete/${item.id}`)
    }


    useEffect(() => {

        if (genericsActionsApi.data && genericsActionsApi.data.length) {

            setGenerics(genericsActionsApi.data)
        }
    }, [genericsActionsApi.data])

    useEffect(() => {
        getGenerics()
    }, [rowsPerPage])

    //Filtering data
    useEffect(() => {
        setdata(generics)
    }, [generics])


    const handleFilter = (e) => {

        console.log('eeeee', e)
        const search_param = e

        if (generics && generics.length > 0 && search_param && search_param !== '') {
            setdata(generics.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(generics);
        }

    };

    return (
        <div>
            {openEditModal && <GenericsFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} item={generic} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            {genericsActionsApi.loading ? <Loading loading={genericsActionsApi.loading} /> : <GenericsTable data={data} columns={columns} rowsPerPage={rowsPerPage} setRowsPerPage={setRowsPerPage}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />}
        </div>
    )
}

export default GenericsList