import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import {
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  Input,
  Switch,
} from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomSwitch,
  Loading,
} from "../../../../components";
import { useFormik } from "formik";
import useApi from "../../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import discountsApi from "../../../../api/discountsApi";

import dayjs from "dayjs";
import "dayjs/locale/en-gb";
import { Modal } from "antd";

export default function PriceDiscountsFormModal({
  ismodalOpen,
  setisModalOpen,
  priceDiscountToEdit,
  modalTitle = "Add new price discount",
  updated,
  setUpdated,
}) {
  // const { isOpen, onOpen, onOpenChange } = useDisclosure();
  const moment = require("moment");

  const [priceDiscount, setPriceDiscounts] = useState(
    priceDiscountToEdit ? priceDiscountToEdit : null
  );
  const [switchLabel, setswitchLabel] = useState("Activate");
  const [switchStatus, setswitchStatus] = useState(false);
  const [errors, setErrors] = useState();
  const discountsActionsApi = useApi(discountsApi.priceDiscountsAction);

  const handlePriceDiscountAction = async (data) => {
    const result = await discountsActionsApi.request(data);

    console.log("result", result);

    if (result.ok) {
      setUpdated(true);
      setisModalOpen(setUpdated);
    } else {
      if (result.data.errors) {
        setErrors(result.data.errors);
      }
      setUpdated(false);
    }
  };

  useEffect(() => {}, [priceDiscount]);

  useEffect(() => {
    if (discountsActionsApi.data) {
      if (discountsActionsApi.data.category) {
        setPriceDiscounts(discountsActionsApi.data.category);
      }
    }
  }, [discountsActionsApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  const formik = useFormik({
    initialValues: {
      start: priceDiscount ? priceDiscount.start : dayjs().format("YYYY-MM-DD"),
      end: priceDiscount ? priceDiscount.end : dayjs().format("YYYY-MM-DD"),
      title: priceDiscount ? priceDiscount.title : "",
      percent: priceDiscount ? priceDiscount.percent : "",
      is_active: priceDiscount ? priceDiscount.is_active : "false",
    },

    validationSchema: Yup.object({
      title: Yup.string()
        .min(3, "Must be 15 characters or more")
        .required("Title is required"),
      percent: Yup.number().required().min(1).label("Percentage"),
      is_active: Yup.bool().label("Status"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      if (priceDiscount) {
        handlePriceDiscountAction({
          action: "UpdatePriceDiscount",
          price_discount_details: {
            id: priceDiscount.id,
            title: values.title,
            percent: values.percent,
            start: values.start,
            end: values.end,
            is_active: values.is_active,
          },
        });
      } else {
        handlePriceDiscountAction({
          action: "CreatePriceDiscount",
          price_discount_details: {
            title: values.title,
            percent: values.percent,
            start: values.start,
            end: values.end,
            is_active: values.is_active,
          },
        });
      }

      // resetForm();
    },
  });

  const handleStartDateChange = (date, dateString) => {
    formik.setFieldValue("start", dateString);
  };
  const handleEndDateChange = (date, dateString) => {
    formik.setFieldValue("end", dateString);
  };

  const handleSwitchChange = (e) => {
    setswitchStatus(e === true);
    if (e === true) {
      formik.setFieldValue("is_active", "true");
      setswitchLabel("Deactivate");
    } else if (e === false) {
      formik.setFieldValue("is_active", "false");
      setswitchLabel("Activate");
    } else {
      formik.setFieldValue("is_active", "");
    }

    console.log("eee", e);
  };

  return (
    <div className="w-full">
      <Modal
        width={720}
        className="w-full text-center"
        title={modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
          >
            <CustomInput
              required={true}
              label="Enter title"
              id="title"
              name="title"
              onChange={formik.handleChange}
              placeholder="Enter title"
              size="large"
              type="text"
              value={formik.values.title}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.percent}
            error={formik.errors.percent}
          >
            <CustomInput
              required={true}
              label="Enter percent"
              id="percent"
              name="percent"
              onChange={formik.handleChange}
              placeholder="Enter percent"
              size="large"
              type="text"
              value={formik.values.percent}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.start}
            error={formik.errors.start}
          >
            <CustomDatePicker
              id="start"
              name="start"
              size="large"
              placeholder="Select start date"
              onChange={handleStartDateChange}
              defaultValue={dayjs(formik.values.start, "YYYY-MM-DD")}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.end}
            error={formik.errors.end}
          >
            <CustomDatePicker
              id="end"
              name="end"
              size="large"
              placeholder="Select end date"
              onChange={handleEndDateChange}
              defaultValue={dayjs(formik.values.end, "YYYY-MM-DD")}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.is_active}
            error={formik.errors.is_active}
          >
            <CustomSwitch
              id="is_active"
              checked={formik.values.is_active === "true"}
              onChange={(e) => handleSwitchChange(e)}
              title={switchLabel}
            />
          </CustomFormItem>
          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
