import React, { useEffect, useState } from 'react'
import PreparationsTable from './PreparationsTable'

import useApi from '../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import PreparationsFormModal from './PreparationsFormModal';
import preparationsApi from '../../api/drugs/preparationsApi';
import { Loading } from '../../components';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Formulation", uid: "formulation_title" },
    { name: "Generics", uid: "generics_string" },

    { name: "Actions", uid: "actions" },
];


function PreparationsList() {
    const [openEditModal, setopenEditModal] = useState(false)
    const navigate = useNavigate()
    const [preparation, setPreparation] = useState()
    const [preparations, setPreparations] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const preparationsActionsApi = useApi(preparationsApi.preparationsAction)

    const getPreparations = async () => {
        await preparationsActionsApi.request({
            "action": "GetPreparations"

        })
    }


    useEffect(() => {
        getPreparations()
    }, [])


    const handleEditAction = (item) => {
        setUpdated(false)
        setopenEditModal(true)
        setPreparation(item)
        setmodalTitle(`${item.title}`)

    }

    const handleAddAction = () => {
        setUpdated(false)
        setopenEditModal(true)
        setmodalTitle("Add new preparation")
        setPreparation(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/preparations/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {

        navigate(`/preparations/delete/${item.id}`)
    }


    useEffect(() => {

        if (preparationsActionsApi.data && preparationsActionsApi.data.length) {

            setPreparations(preparationsActionsApi.data)
        }

        console.log('preparationsActionsApi.data', preparationsActionsApi.data)
    }, [preparationsActionsApi.data])

    useEffect(() => {
        getPreparations()
    }, [updated])

    //Filtering data
    useEffect(() => {
        setdata(preparations)
    }, [preparations])


    const handleFilter = (e) => {


        const search_param = e

        if (preparations && preparations.length > 0 && search_param && search_param !== '') {
            setdata(preparations.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(preparations);
        }

    };

    return (
        <div>
            {openEditModal && <PreparationsFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} item={preparation} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            {preparationsActionsApi.loading ? <Loading loading={preparationsActionsApi.loading} /> : <PreparationsTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />}
        </div>
    )
}

export default PreparationsList