import React, { useEffect, useState } from 'react'
import DesignationsTable from './DesignationsTable'

import useApi from '../../../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import { getLoggedInUser } from '../../../../helpers/authUtils';
import DesignationsFormModal from './DesignationsFormModal';
import designationsApi from '../../../../api/employees/designationsApi';
import { Loading } from '../../../../components';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Cadre", uid: "cadre_title" },
    { name: "Tenure", uid: "tenure" },
    { name: "Description", uid: "description" },

    { name: "Actions", uid: "actions" },
];


function DesignationsList() {

    const [openDepartmentFormModal, setopenDesignationsFormModal] = useState(false)
    const navigate = useNavigate()
    const [designation, setDesignation] = useState()
    const [designations, setDesignations] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const designationsActionsApi = useApi(designationsApi.designationsAction)

    const [user, setUser] = useState()



    useEffect(() => {
        setUser(getLoggedInUser())

    }, [])

    const getEntityDesignations = async () => {
        setDesignations([])
        await designationsActionsApi.request({
            "action": "EntityDesignations"

        })
    }



    useEffect(() => {
        getEntityDesignations()
    }, [])

    useEffect(() => {
        console.log("")

        if (user) {

            getEntityDesignations(user)
        }


    }, [openDepartmentFormModal])


    const handleEditAction = (item) => {

        setopenDesignationsFormModal(true)

        // setUpdated(false)

        setDesignation(item)
        setmodalTitle(`${item.title}`)

    }

    const handleAddAction = () => {


        setopenDesignationsFormModal(true)

        setUpdated(false)

        setmodalTitle("Add new department")
        setDesignation(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/employees/designations/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {

        navigate(`/employees/designations/delete/${item.id}`)
    }


    useEffect(() => {

        if (designationsActionsApi.data && designationsActionsApi.data.length) {

            setDesignations(designationsActionsApi.data)
        }

        console.log('designationsActionsApi.data', designationsActionsApi.data)
    }, [designationsActionsApi.data])

    useEffect(() => {

    }, [openDepartmentFormModal])

    //Filtering data
    useEffect(() => {
        setdata(designations)
    }, [designations])


    const handleFilter = (e) => {


        const search_param = e

        if (designations && designations.length > 0 && search_param && search_param !== '') {
            setdata(designations.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(designations);
        }

    };

    return designationsActionsApi.loading ? <Loading loading={designationsActionsApi.loading} /> : (
        <div>

            {openDepartmentFormModal && <DesignationsFormModal openEditModal={openDepartmentFormModal} setopenEditModal={setopenDesignationsFormModal} designation={designation} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <DesignationsTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default DesignationsList