import React, { useEffect, useState } from 'react'
import { useLocation, useParams } from 'react-router-dom'
import useApi from '../../hooks/useApi'
import retailerReceiptsApi from '../../api/retailers/retailerReceiptsApi'
import { Avatar, Card, CardFooter, CardHeader, CardBody, Input, Divider, Tab, Tabs, RadioGroup } from "@heroui/react";
import { Button, CustomRadioItem, DeleteIcon, Header, Loading, PlusIcon, SearchIcon } from '../../components';
import { AiOutlineShoppingCart } from 'react-icons/ai';
import { ToastContainer, toast } from "react-toastify";
import paymentsApi from '../../api/paymentsApi';
import useScreenSize from '../../hooks/useScreenSize';
import { useStateContext } from '../../contexts/ContextProvider';
import { createOrderItem, removeOrderItem, updateOtherOrderDetails, } from '../../helpers/retailerHelpers';
import RequiredQuantityFormModal from '../retailers/orders/RequiredQuantityFormModal';
import ShoppingShippingAddressModal from './ShoppingShippingAddressModal';
import MpesaNumberFormModal from '../retailers/orders/MpesaNumberFormModal';
import CashPaymentFormModal from '../retailers/orders/CashPaymentFormModal';

function ShopFront({ route }) {
    const { id } = useParams()
    const location = useLocation()
    const [selected, setSelected] = React.useState("products");
    const screenSize = useScreenSize();
    const {

        currentColor,
        successColor,
        loggedInUser

    } = useStateContext();

    console.log('logg', loggedInUser)
    // const [entity, setentity] = useState()
    const [selectedOrder, setselectedOrder] = useState();
    const [currentEmploymentDetails, setcurrentEmploymentDetails] = useState();
    const [draftCustomerOrders, setdraftCustomerOrders] = useState([]);
    const [openRequiredQuantityModal, setopenRequiredQuantityModal] = useState(false)
    const [retailerReceipts, setRetailerReceipts] = useState([])
    const [quantity, setQuantity] = useState()
    const [selectedRetailerReceipt, setselectedRetailerReceipt] = useState()
    const [selectedOrderItems, setselectedOrderItems] = useState([]);
    const [draftId, setdraftId] = useState()
    const [selectedPaymentMethod, setselectedPaymentMethod] = useState(selectedOrder && selectedOrder.payment_method ? selectedOrder.payment_method : '')
    const [selectedDeliveryOption, setselectedDeliveryOption] = useState(selectedOrder && selectedOrder.delivery_method ? selectedOrder.delivery_method : '')
    const [orderTotal, setorderTotal] = useState()
    const [cashbalance, setcashbalance] = useState(0)
    const [tenderedAmount, settenderedAmount] = useState()
    const [data, setdata] = useState([])
    const [errors, setErrors] = useState([])
    const [openShippingAddressModal, setopenShippingAddressModal] = useState(false)
    const [shippingDetails, setshippingDetails] = useState()

    const [openMpesaNumberModal, setopenMpesaNumberModal] = useState(false)
    const [mpesaNumber, setmpesaNumber] = useState()

    const [openCashpaymentModal, setopenCashpaymentModal] = useState(false)


    useEffect(() => {
        setselectedOrder(location.state.order)
    }, [])

    const retailerReceiptsActionsApi = useApi(retailerReceiptsApi.retailerReceiptsActionJoint)


    const getEntityInventory = async (data) => {
        await retailerReceiptsActionsApi.request(data)
    }

    useEffect(() => {
        if (selectedOrder && selectedOrder.entity) {
            getEntityInventory({
                "action": "GetRetailerReceiptsForEntity",
                "entity": selectedOrder.entity
            })
        }
    }, [selectedOrder])




    //Retrieve payment methods
    const [paymentMethods, setpaymentMethods] = useState([])
    const paymentMethodsActionsApi = useApi(paymentsApi.paymentMethodsAction)

    const getPaymentMethods = async () => {
        await paymentMethodsActionsApi.request()
    }

    useEffect(() => {
        getPaymentMethods()
    }, [])
    useEffect(() => {

        if (paymentMethodsActionsApi.data && paymentMethodsActionsApi.data.length) {

            setpaymentMethods(paymentMethodsActionsApi.data)
        }

        console.log('paymentMethodsActionsApi.data', paymentMethodsActionsApi.data)
    }, [paymentMethodsActionsApi.data])

    //Add item to cart
    const handleAddToCart = (item) => {
        setopenRequiredQuantityModal(!openRequiredQuantityModal)
        setselectedRetailerReceipt(item)

    }

    //Remove item for order
    const handleRemoveOrderItem = (item) => {
        console.log('Item', item)
        const order = removeOrderItem(item.draft_id, item.retailer_receipt)
        setselectedOrderItems(order.orderItems)
    }

    const handleSelectPaymentOption = (e) => {
        console.log('value of selected payment', e.target.value)


        if (!selectedDeliveryOption) {
            toast.error('Select delivery option first')
            setselectedPaymentMethod(null)
        } else {
            const payment_method = paymentMethods.find(x => x.id === e.target.value)
            if (payment_method) {
                setselectedPaymentMethod(payment_method.title)
                const data = {
                    "payment_method": payment_method

                }
                setselectedOrder(updateOtherOrderDetails(selectedOrder && selectedOrder.draft_id, data))
            }

        }

    }

    //Retrieve and filter data
    useEffect(() => { setdata(retailerReceipts) }, [retailerReceipts])

    useEffect(() => {

        if (retailerReceiptsActionsApi.data && retailerReceiptsActionsApi.data.length) {

            setRetailerReceipts(retailerReceiptsActionsApi.data)
        }

        console.log('retailerReceiptsActionsApi.data', retailerReceiptsActionsApi.data)
    }, [retailerReceiptsActionsApi.data])

    const handleFilter = (e) => {


        const search_param = e.target.value

        if (retailerReceipts && retailerReceipts.length > 0 && search_param && search_param !== '') {
            setdata(retailerReceipts.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(retailerReceipts);
        }

    };

    const handleCloseOrder = () => { }

    const handleCreateNewOrder = () => {
        console.log('Create new order')
    }

    //Create order item
    useEffect(() => {
        if (quantity && selectedRetailerReceipt) {
            const orderItem = createOrderItem(
                draftId,
                parseInt(quantity),
                selectedRetailerReceipt
            );

            const currentOrderItems = selectedOrderItems;
            console.log("item c", currentOrderItems);

            const exists = selectedOrderItems.find(
                (x) => x.retailer_receipt === orderItem.retailer_receipt
            );

            if (exists) {
                console.log("Iko");
                const without = currentOrderItems.filter(
                    (x) => x.retailer_receipt !== orderItem.retailer_receipt
                );
                setselectedOrderItems([...without, orderItem]);
            } else {
                setselectedOrderItems([...currentOrderItems, orderItem]);
                console.log("Hakuna");
            }
        }

    }, [quantity, selectedRetailerReceipt, openRequiredQuantityModal])



    //Selected delivery method
    useEffect(() => {
        if (selectedDeliveryOption) {
            if (selectedDeliveryOption && selectedDeliveryOption === 'DELIVERY') {
                //Open shipping details modal
                setopenShippingAddressModal(true)
            } else {
                //Close shipping details modal
                setopenShippingAddressModal(false)
            }

            //Update order delivery option
            setselectedOrder(updateOtherOrderDetails(selectedOrder && selectedOrder.draft_id, { "delivery_method": selectedDeliveryOption }))
        }

    }, [selectedDeliveryOption])

    return retailerReceiptsActionsApi.loading ? <Loading loading={retailerReceiptsActionsApi.loading} /> : <div>
        {
            screenSize.width < 768 ?
                <div>
                    <Card className="max-w-full ">
                        <Header category="Orders" title={selectedOrder ? selectedOrder.entity_title : ""} addButtonVisible={false} addButtonTitle="Create New Order" handleAddButtonAction={handleCreateNewOrder} />
                        <ToastContainer position="bottom-center" theme="colored" />
                        <CardBody className="overflow-hidden">
                            <Tabs
                                fullWidth
                                size="md"
                                aria-label="Tabs form"
                                selectedKey={selected}
                                onSelectionChange={setSelected}
                            >
                                <Tab key="products" title="Products">
                                    <div className='max-h-[720px] bg-gray-100 overflow-y-scroll'>
                                        <h1 className='text-large font-bold text-center'>Products List</h1>
                                        <Card className='max-w-full mx-1 md:mx-5 my-1'>
                                            <CardBody>
                                                <Input
                                                    label="Search"
                                                    isClearable
                                                    radius="lg"

                                                    onChange={(e) => handleFilter(e)}
                                                    classNames={{
                                                        label: "text-black/50 dark:text-white/90",
                                                        input: [
                                                            "bg-transparent",
                                                            "text-black/90 dark:text-white/90",
                                                            "placeholder:text-default-700/50 dark:placeholder:text-white/60",
                                                        ],
                                                        innerWrapper: "bg-transparent",
                                                        inputWrapper: [
                                                            "shadow-xl",
                                                            "bg-default-200/50",
                                                            "dark:bg-default/60",
                                                            "backdrop-blur-xl",
                                                            "backdrop-saturate-200",
                                                            "hover:bg-default-200/70",
                                                            "dark:hover:bg-default/70",
                                                            "group-data-[focused=true]:bg-default-200/50",
                                                            "dark:group-data-[focused=true]:bg-default/60",
                                                            "!cursor-text",
                                                        ],
                                                    }}
                                                    placeholder="Type to search..."
                                                    startContent={
                                                        <SearchIcon className="text-black/50 dark:text-white/90 text-slate-400 pointer-events-none flex-shrink-0" />
                                                    }
                                                />
                                            </CardBody>
                                        </Card>
                                        {
                                            data && data.length > 0 && data.map(item =>
                                                <Card className='max-w-full mx-1 md:mx-5 my-2'>
                                                    <CardHeader className="justify-between">
                                                        <div className="flex gap-5 items-center">
                                                            <Avatar className="w-20 h-20 text-large" isBordered radius="sm" size="lg" src={item.images && item.images[0] ? item.images[0].image : ""} name={item.title} />
                                                            <div className="flex flex-col gap-1 items-start justify-center">
                                                                <h4 className="text-medium font-semibold leading-none text-default-600">{item.title}</h4>
                                                                <h5 className="text-medium tracking-tight text-default-400">KES {item.unit_selling_price}</h5>
                                                                <h6 className="text-medium tracking-tight text-default-400">In Stock:  {item.unit_quantity}</h6>
                                                            </div>
                                                        </div>
                                                        <AiOutlineShoppingCart onClick={() => handleAddToCart(item)} className='cursor-pointer hover:resize-x' size={24} color={selectedOrder && selectedOrder.orderItems && selectedOrder.orderItems.length
                                                            && selectedOrder.orderItems && selectedOrder.orderItems.length
                                                            && selectedOrder.orderItems.filter(x => x.retailer_receipt === item.id).length > 0 ? successColor : currentColor} />
                                                    </CardHeader>

                                                </Card>
                                            )
                                        }

                                        {openRequiredQuantityModal && <RequiredQuantityFormModal openEditModal={openRequiredQuantityModal} setopenEditModal={setopenRequiredQuantityModal} quantity={quantity} setQuantity={setQuantity} />}
                                    </div>
                                </Tab>
                                <Tab key="cart" title="Customer Order">
                                    <div className='max-h-[720px] bg-gray-100 overflow-y-scroll'>
                                        <h1 className='text-large font-bold text-center'>Order Summary</h1>
                                        <Card className='max-w-full mx-1 md:mx-5 my-1'>
                                            <CardBody>
                                                <div className='grid grid-cols-2 md:grid-cols-4 gap-y-2'>
                                                    <div>
                                                        <p className='text-slate-500' >Customer Name</p>
                                                        <p className='font-bold text-gray-400'>{loggedInUser && loggedInUser.name}</p>
                                                    </div>
                                                    <div>
                                                        <p className='text-slate-500'>Customer Phone</p>
                                                        <p className='font-bold text-gray-400'>{loggedInUser && loggedInUser.phone}</p>
                                                    </div>

                                                    <div>
                                                        <p className='text-slate-500'>Total Amount</p>
                                                        <p className='font-bold text-gray-400'>KES {selectedOrderItems && selectedOrderItems
                                                            .reduce((acc, item) => acc + item.item_price_total, 0).toFixed(2)
                                                        }</p>
                                                    </div>

                                                    <div>
                                                        <p className='text-slate-500'>Items in Order</p>
                                                        <p className='font-bold text-gray-400'> {selectedOrderItems && selectedOrderItems
                                                            .length
                                                        }</p>
                                                    </div>
                                                </div>
                                            </CardBody>
                                        </Card>
                                        {
                                            selectedOrderItems.map(item =>
                                                <Card className='max-w-full mx-1 md:mx-5 my-2'>
                                                    <CardHeader className="justify-between">
                                                        <div className="flex gap-5 items-center">
                                                            <Avatar className="w-20 h-20 text-large" isBordered radius="sm" size="lg" src={item.image ? item.image : ""} name={item.title} />
                                                            <div className="flex flex-col gap-1 items-start justify-center">
                                                                <h4 className="text-medium font-semibold leading-none text-default-600">{item.product_title}</h4>
                                                                <h5 className="text-medium tracking-tight text-default-400">KES {item.unit_selling_price}</h5>
                                                                <h6 className="text-medium tracking-tight text-default-400">Quantity:  {item.purchased_quantity.toString()}</h6>
                                                                <h6 className="text-medium tracking-tight text-default-400">Item total: KES {item.item_price_total.toString()}</h6>
                                                            </div>
                                                        </div>
                                                        <DeleteIcon onClick={() => handleRemoveOrderItem(item)} className='cursor-pointer hover:resize-x' size={24} color={currentColor} />
                                                    </CardHeader>

                                                </Card>
                                            )
                                        }

                                        <Card className='max-w-full mx-1 md:mx-5 my-2'>
                                            <CardBody>
                                                <RadioGroup defaultValue={selectedDeliveryOption} onChange={(e) => setselectedDeliveryOption(e.target.value)} orientation="horizontal" label="Delivery options" description="Selected plan can be changed at any time.">

                                                    <CustomRadioItem description="Order to be picked up by customer" value="PICKUP">
                                                        Pick Up
                                                    </CustomRadioItem>
                                                    <CustomRadioItem description="Order to be delivered to customer" value="DELIVERY">
                                                        Delivery
                                                    </CustomRadioItem>

                                                </RadioGroup>
                                            </CardBody>

                                        </Card>

                                        <Card className='max-w-full mx-1 md:mx-5 my-2'>
                                            <CardBody>
                                                <RadioGroup defaultValue={selectedPaymentMethod} onChange={(e) => handleSelectPaymentOption(e)} orientation="horizontal" label="Payment Options" description="Payment plan can also be changed after order is saved.">


                                                    {paymentMethods && paymentMethods.length && paymentMethods.map(x => <CustomRadioItem description="Order to be delivered to customer" value={x.id}>
                                                        <Avatar name={x.title} src={x.images && x.images.length ? x.images[0].image : ""} />
                                                        {x.title}
                                                    </CustomRadioItem>
                                                    )}



                                                </RadioGroup>
                                            </CardBody>

                                        </Card>
                                        <Card className='max-w-full mx-1 md:mx-5 my-2'><Button onClick={handleCloseOrder} text="Save Order" className='m-1'>Save Order</Button></Card>
                                        {openCashpaymentModal && <CashPaymentFormModal openEditModal={openCashpaymentModal} setopenEditModal={setopenCashpaymentModal} orderTotal={orderTotal} tenderedAmount={tenderedAmount} setTenderedAmount={settenderedAmount} cashbalance={cashbalance} setcashbalance={setcashbalance} />}
                                        {openMpesaNumberModal && <MpesaNumberFormModal openEditModal={openMpesaNumberModal} setopenEditModal={setopenMpesaNumberModal} mpesaNumber={mpesaNumber} setmpesaNumber={setmpesaNumber} />}
                                        {openShippingAddressModal && <ShoppingShippingAddressModal
                                            openEditModal={openShippingAddressModal}
                                            setopenEditModal={setopenShippingAddressModal}
                                            shippingDetails={shippingDetails}
                                            setshippingDetails={setshippingDetails}
                                            selectedOrder={selectedOrder}
                                            setselectedOrder={setselectedOrder} />}
                                        {openRequiredQuantityModal && <RequiredQuantityFormModal openEditModal={openRequiredQuantityModal} setopenEditModal={setopenRequiredQuantityModal} quantity={quantity} setQuantity={setQuantity} />}
                                    </div>
                                </Tab>
                            </Tabs>

                        </CardBody>

                    </Card>
                </div>
                :
                < div className='grid md:grid-cols-2 gap-6'>

                    <div className='max-h-[720px] bg-gray-100 overflow-y-scroll'>

                        <ToastContainer position="bottom-center" theme="colored" />
                        <Header category="Orders" title={selectedOrder ? selectedOrder.entity_title : ''} addButtonVisible={false} addButtonTitle="Create New Order" handleAddButtonAction={handleCreateNewOrder} />
                        <h1 className='text-large font-bold text-center'>Products List</h1>

                        <Card className='max-w-full mx-1 md:mx-5 my-1'>
                            <CardBody>
                                <Input
                                    label="Search"
                                    isClearable
                                    radius="lg"

                                    onChange={(e) => handleFilter(e)}
                                    classNames={{
                                        label: "text-black/50 dark:text-white/90",
                                        input: [
                                            "bg-transparent",
                                            "text-black/90 dark:text-white/90",
                                            "placeholder:text-default-700/50 dark:placeholder:text-white/60",
                                        ],
                                        innerWrapper: "bg-transparent",
                                        inputWrapper: [
                                            "shadow-xl",
                                            "bg-default-200/50",
                                            "dark:bg-default/60",
                                            "backdrop-blur-xl",
                                            "backdrop-saturate-200",
                                            "hover:bg-default-200/70",
                                            "dark:hover:bg-default/70",
                                            "group-data-[focused=true]:bg-default-200/50",
                                            "dark:group-data-[focused=true]:bg-default/60",
                                            "!cursor-text",
                                        ],
                                    }}
                                    placeholder="Type to search..."
                                    startContent={
                                        <SearchIcon className="text-black/50 dark:text-white/90 text-slate-400 pointer-events-none flex-shrink-0" />
                                    }
                                />
                            </CardBody>
                        </Card>
                        {
                            data && data.length > 0 && data.map(item =>
                                <Card className='max-w-full mx-1 md:mx-5 my-2'>
                                    <CardHeader className="justify-between">
                                        <div className="flex gap-5 items-center">
                                            <Avatar className="w-20 h-20 text-large" isBordered radius="sm" size="lg" src={item.images && item.images[0] ? item.images[0].image : ""} name={item.title} />
                                            <div className="flex flex-col gap-1 items-start justify-center">
                                                <h4 className="text-medium font-semibold leading-none text-default-600">{item.title}</h4>
                                                <h5 className="text-medium tracking-tight text-default-400">KES {item.unit_selling_price}</h5>
                                                <h6 className="text-medium tracking-tight text-default-400">In Stock:  {item.unit_quantity}</h6>
                                            </div>
                                        </div>
                                        <AiOutlineShoppingCart onClick={() => handleAddToCart(item)} className='cursor-pointer hover:resize-x' size={24} color={selectedOrder && selectedOrder.orderItems.filter(x => x.retailer_receipt === item.id).length > 0 ? successColor : currentColor} />
                                    </CardHeader>

                                </Card>
                            )
                        }

                        {openRequiredQuantityModal && <RequiredQuantityFormModal openEditModal={openRequiredQuantityModal} setopenEditModal={setopenRequiredQuantityModal} quantity={quantity} setQuantity={setQuantity} />}
                    </div>
                    <div className='max-h-[720px] bg-gray-100 overflow-y-scroll'>
                        <h1 className='text-large font-bold text-center'>Order Summary</h1>
                        <Card className='max-w-full mx-1 md:mx-5 my-1'>
                            <CardBody>
                                <div className='grid grid-cols-2 md:grid-cols-4'>
                                    <div>
                                        <p className='text-slate-500'>Customer Name</p>
                                        <p className='font-bold text-gray-400'>{loggedInUser && loggedInUser.name}</p>
                                    </div>
                                    <div>
                                        <p className='text-slate-500'>Customer Phone</p>
                                        <p className='font-bold text-gray-400'>{loggedInUser && loggedInUser.phone}</p>
                                    </div>
                                    <div>
                                        <p className='text-slate-500'>Total Amount</p>
                                        <p className='font-bold text-gray-400'>KES {selectedOrderItems && selectedOrderItems
                                            .reduce((acc, item) => acc + item.item_price_total, 0).toFixed(2)
                                        }</p>
                                    </div>
                                    <div>
                                        <p className='text-slate-500'>Items in Order</p>
                                        <p className='font-bold text-gray-400'>{selectedOrderItems && selectedOrderItems
                                            .length
                                        }</p>
                                    </div>
                                </div>
                            </CardBody>
                        </Card>
                        {
                            selectedOrderItems.map(item =>
                                <Card className='max-w-full mx-1 md:mx-5 my-2'>
                                    <CardHeader className="justify-between">
                                        <div className="flex gap-5 items-center">
                                            <Avatar className="w-20 h-20 text-large" isBordered radius="sm" size="lg" src={item.image ? item.image : ""} name={item.title} />
                                            <div className="flex flex-col gap-1 items-start justify-center">
                                                <h4 className="text-medium font-semibold leading-none text-default-600">{item.product_title}</h4>
                                                <h5 className="text-medium tracking-tight text-default-400">KES {item.unit_selling_price}</h5>
                                                <h6 className="text-medium tracking-tight text-default-400">Quantity:  {item.purchased_quantity.toString()}</h6>
                                                <h6 className="text-medium tracking-tight text-default-400">Item total: KES {item.item_price_total.toString()}</h6>
                                            </div>
                                        </div>
                                        <DeleteIcon onClick={() => handleRemoveOrderItem(item)} className='cursor-pointer hover:resize-x' size={24} color={currentColor} />
                                    </CardHeader>

                                </Card>
                            )
                        }

                        <Card className='max-w-full mx-1 md:mx-5 my-2'>
                            <CardBody>
                                <RadioGroup defaultValue={selectedDeliveryOption} onChange={(e) => setselectedDeliveryOption(e.target.value)} orientation="horizontal" label="Delivery options" description="Selected plan can be changed at any time.">

                                    <CustomRadioItem description="Order to be picked up by customer" value="PICKUP">
                                        Pick Up
                                    </CustomRadioItem>
                                    <CustomRadioItem description="Order to be delivered to customer" value="DELIVERY">
                                        Delivery
                                    </CustomRadioItem>

                                </RadioGroup>
                            </CardBody>

                        </Card>

                        <Card className='max-w-full mx-1 md:mx-5 my-2'>
                            <CardBody>

                                <RadioGroup defaultValue={selectedPaymentMethod} onChange={(e) => handleSelectPaymentOption(e)} orientation="horizontal" label="Payment Options" description="Payment plan can also be changed after order is saved.">


                                    {paymentMethods && paymentMethods.length && paymentMethods.map(x => <CustomRadioItem description={x.description} value={x.id}>
                                        <Avatar name={x.title} src={x.images && x.images.length ? x.images[0].image : ""} />
                                        {x.title}
                                    </CustomRadioItem>
                                    )}



                                </RadioGroup>
                            </CardBody>
                        </Card>
                        <Card className='max-w-full mx-1 md:mx-5 my-2'><Button text="Save Order" onClick={handleCloseOrder} className='m-1 h-12 rounded-md'>Save Order</Button></Card>
                        {openCashpaymentModal && <CashPaymentFormModal openEditModal={openCashpaymentModal} setopenEditModal={setopenCashpaymentModal} orderTotal={orderTotal} tenderedAmount={tenderedAmount} setTenderedAmount={settenderedAmount} cashbalance={cashbalance} setcashbalance={setcashbalance} />}
                        {openMpesaNumberModal && <MpesaNumberFormModal openEditModal={openMpesaNumberModal} setopenEditModal={setopenMpesaNumberModal} mpesaNumber={mpesaNumber} setmpesaNumber={setmpesaNumber} />}
                        {openShippingAddressModal && <ShoppingShippingAddressModal openEditModal={openShippingAddressModal} setopenEditModal={setopenShippingAddressModal} shippingDetails={shippingDetails} setshippingDetails={setshippingDetails} />}
                        {openRequiredQuantityModal && <RequiredQuantityFormModal openEditModal={openRequiredQuantityModal} setopenEditModal={setopenRequiredQuantityModal} quantity={quantity} setQuantity={setQuantity} />}

                    </div>

                </div>
        }
    </div>
}

export default ShopFront