import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomTextArea,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import { Modal } from "antd";
import designationsApi from "../../../api/employees/designationsApi";
import rolesApi from "../../../api/rolesApi";
import { useStateContext } from "../../../contexts/ContextProvider";
import clustersApi from "../../../api/clustersApi";

export default function RolesFormModal({
  ismodalOpen,
  setisModalOpen,
  role,
  modalTitle = "Add new role",
  updated,
  setUpdated,
  user,
}) {
  const { dangerColor, currentColor } = useStateContext();
  const rolesActionsApi = useApi(rolesApi.rolesAction);

  const [errors, setErrors] = useState();

  useEffect(() => {}, [role]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const handleRoleAction = async (data) => {
    await rolesActionsApi.request(data);

    // if (result.ok) {
    //   //   setUpdated(true);
    //   //   setisModalOpen(setUpdated);
    //   if (result.data.errors && result.data.errors.length) {
    //     setErrors(result.data.errors);
    //   }
    // } else {
    //   setUpdated(false);
    //   setErrors(result.data.errors);
    // }
    // console.log("result ar role action", result.data.errors);
  };

  useEffect(() => {
    if (rolesActionsApi.data && rolesActionsApi.data.role) {
      toast.success(rolesActionsApi.data.response_message);
      setisModalOpen(false);
    }

    if (
      rolesActionsApi.data &&
      rolesActionsApi.data.errors &&
      rolesActionsApi.data.errors.length
    ) {
      setErrors(rolesActionsApi.data.errors);
    }
  }, [rolesActionsApi.data]);

  const formik = useFormik({
    initialValues: {
      title: role ? role.title : "",
      cluster: role ? { label: role.cluster_title, value: role.cluster } : null,
      description: role ? role.description : "",
    },

    validationSchema: Yup.object({
      title: Yup.string()
        .min(3, "Must be 15 characters or more")
        .required("Title is required"),
      cluster: Yup.object().required().label("Cluster"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      if (role) {
        handleRoleAction({
          action: "UpdateRole",
          role_details: {
            id: role.id,
            title: values.title,
            cluster: values.cluster.value,
            description: values.description,
          },
        });
      } else {
        handleRoleAction({
          action: "CreateRole",
          role_details: {
            title: values.title,
            cluster: values.cluster.value,
            description: values.description,
          },
        });
      }
      // resetForm();
    },
  });

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  //Retrieve roles
  const [roles, setRoles] = useState([]);

  const getRoles = async () => {
    await rolesActionsApi.request({
      action: "GetEntityRoles",
    });
  };
  useEffect(() => {
    getRoles();
  }, []);

  useEffect(() => {
    if (rolesActionsApi.data && rolesActionsApi.data.length) {
      setRoles(
        rolesActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("roles", roles);
  }, [rolesActionsApi.data]);

  //Retrieve clusters
  const [clusters, setClusters] = useState([]);
  const clustersActionsApi = useApi(clustersApi.clustersAction);
  const getClusters = async () => {
    await clustersActionsApi.request({
      action: "GetClusters",
    });
  };
  useEffect(() => {
    getClusters();
  }, []);

  useEffect(() => {
    if (clustersActionsApi.data && clustersActionsApi.data.length) {
      setClusters(
        clustersActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }
    console.log("clusters", clusters);
  }, [clustersActionsApi.data]);

  return (
    <div className="w-full">
      <Modal
        width={500}
        className="w-full text-center"
        title={modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        {errors && errors.length ? (
          <div>
            {errors.map((x) => {
              return <p className="text-red-400 font-bold text-medium">{x}</p>;
            })}
          </div>
        ) : (
          <div></div>
        )}

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className="grid grid-cols-1 gap-2  items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.cluster}
            error={formik.errors.cluster}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="cluster"
              id="cluster"
              label="Select cluster"
              size="large"
              onChange={(value) => formik.setFieldValue("cluster", value)}
              value={formik.values.cluster}
              placeholder="Select role cluster"
              options={clusters}
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
          >
            <CustomInput
              required={true}
              id="title"
              name="title"
              onChange={formik.handleChange}
              placeholder="Enter role title"
              size="large"
              type="text"
              value={formik.values.title}
              label="Enter role title"
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.description}
            error={formik.errors.description}
          >
            <CustomTextArea
              className="flex-1 w-full"
              required={true}
              id="description"
              name="description"
              onChange={formik.handleChange}
              placeholder="Enter role description"
              size="large"
              type="text"
              rows={3}
              value={formik.values.description}
              label="Enter role description"
            />
          </CustomFormItem>
          <div className="grid grid-cols-2">
            <div className="">
              <Button
                onClick={() => setisModalOpen(false)}
                style={{ background: dangerColor }}
                className="w-36 rounded-md"
                color="primary"
                type="button"
              >
                Cancel
              </Button>
            </div>
            <div className="">
              <Button
                style={{ background: currentColor }}
                className="w-36 rounded-md"
                color="primary"
                type="submit"
              >
                Submit
              </Button>
            </div>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
