import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import makeAnimated from "react-select/animated"
import AsyncSelect from "react-select/async";
import CreateSelect from "react-select/creatable";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, Input, Link, Textarea, Select, SelectItem } from "@heroui/react";
import { Loading } from '../../components';
import { useFormik } from "formik";
import useApi from "../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import { animals } from "./data";
import drugClassesApi from "../../api/drugs/drugClassesApi";
import { Badge } from "reactstrap";
import bodySystemsApi from "../../api/drugs/bodySystemsApi";

export default function DrugClassesFormModal({ openEditModal, setopenEditModal, item, updated, setUpdated, modalTitle }) {
    const animatedComponent = makeAnimated();

    const [drugClass, setDrugClass] = useState(item ? item : null)

    const [errors, setErrors] = useState();

    const [bodySystems, setBodySystems] = useState([])
    const bodySystemActionsApi = useApi(bodySystemsApi.bodySystemsAction)

    const getAllBodySystems = async () => {
        await bodySystemActionsApi.request({
            "action": "GetBodySystems"

        })
    }

    const loadBodySystemsOptions = async (inputText = "", callback) => {
        // searchFormulations({
        //     action: "SearchFormulations",
        //     searchQuery: inputText,
        // });
        getAllBodySystems()

        callback(bodySystems.map((i) => ({ label: i.title, value: i.id })));
    };

    useEffect(() => {
        getAllBodySystems()
    }, [])

    useEffect(() => {

        if (bodySystemActionsApi.data && bodySystemActionsApi.data.length) {

            setBodySystems(bodySystemActionsApi.data.map((i) => ({ label: i.title, value: i.id })))
        }
    }, [bodySystemActionsApi.data])
    const drugClassesActionsApi = useApi(drugClassesApi.drugClassesAction);

    const handleDrugClassAction = async (data) => {
        const result = await drugClassesActionsApi.request(data);

        if (result.ok) {
            setUpdated(true)
            setopenEditModal(false)
        } else {
            setErrors(result.data.errors)
        }

    }



    useEffect(() => { }, [drugClass])

    useEffect(() => {

        if (drugClassesActionsApi.data) {
            if (drugClassesActionsApi.data.category) {
                setDrugClass(drugClassesActionsApi.data.category)
            }
        }
    }, [drugClassesActionsApi.data])

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    const formik = useFormik({
        initialValues: {
            title: drugClass ? drugClass.title : '',
            description: drugClass ? drugClass.description : '',
            body_system: drugClass ? { 'label': drugClass.system_details.title, 'value': drugClass.system_details.id } : ''
        },

        validationSchema: Yup.object({
            title: Yup.string()
                .min(3, "Must be 15 characters or more")
                .required("Title is required"),
        }),
        onSubmit: (values, { resetForm }) => {
            console.log('VALZ', values)
            //Dispatch action


            setErrors([])

            if (item) {

                handleDrugClassAction({
                    "action": "UpdateDrugClass",
                    "drug_class_details": {
                        "id": drugClass.id,
                        "title": values.title,
                        "description": values.description,
                        "body_system": values.body_system.value
                    }
                })
            } else {
                handleDrugClassAction({
                    "action": "CreateDrugClass",
                    "drug_class_details": {
                        "title": values.title,
                        "description": values.description,
                        "body_system": values.body_system.value
                    }
                })
            }
            resetForm();
        },
    });


    return (
        <>

            <Modal
                isOpen={openEditModal}
                placement="center"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            {drugClassesActionsApi.loading ? <Loading /> : <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1">{modalTitle}</ModalHeader>
                                <ModalBody>
                                    <Input
                                        style={{
                                            borderColor: 'primary'
                                        }}
                                        id="title"
                                        name="title"
                                        autoFocus
                                        label="Title"
                                        placeholder="Enter title"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.title}
                                        value={formik.values.title}
                                    />
                                    <div>
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="body_system"
                                            key="body_system"
                                            name="body_system"

                                            components={animatedComponent}
                                            placeholder="Select body system"
                                            isClearable
                                            value={formik.values.body_system}
                                            onChange={(value) => formik.setFieldValue("body_system", value)}
                                            options={bodySystems}
                                        />
                                        {formik.touched.body_system && formik.errors.body_system ? (
                                            <p color="danger">{formik.errors.body_system}</p>
                                        ) : null}
                                    </div>
                                    <Textarea
                                        id="description"
                                        key="description"
                                        name="description"
                                        label="Description"
                                        placeholder="Type description"
                                        variant="bordered"
                                        defaultValue={formik.values.description}
                                        value={formik.values.description}
                                        onBlur={formik.handleBlur}
                                        onChange={formik.handleChange}
                                    />
                                    {/* <div>
                                        <AsyncSelect
                                            components={animatedComponent}
                                            placeholder="Select formulation"
                                            isClearable
                                            value={formik.values.formulation}
                                            onChange={(value) => formik.setFieldValue("formulation", value)}
                                            loadOptions={loadBodySystemsOptions}
                                        />
                                        {formik.touched.formulation && formik.errors.formulation ? (
                                            <p color="danger">{formik.errors.formulation}</p>
                                        ) : null}
                                    </div> */}

                                </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenEditModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>}


                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
