import { Avatar, Card, CardHeader, Input } from "@heroui/react"
import React, { useEffect, useState } from 'react'
import { SearchIcon } from '../../components'
import useApi from '../../hooks/useApi'
import entitiesApi from '../../api/entitiesApi'
import { useStateContext } from '../../contexts/ContextProvider'
import { useNavigate } from 'react-router-dom'


function ShopsList() {

    const entitiesActionsApi = useApi(entitiesApi.entitiesAction)
    const [searchText, setsearchText] = useState()

    const { currentColor } = useStateContext

    const navigate = useNavigate()

    const [retailers, setretailers] = useState()

    const handleSearchTextChange = (e) => {


        if (e.target.value !== "") {
            setsearchText(e.target.value)
        }

    }
    const searchRetailer = async (text) => {
        await entitiesActionsApi.request({
            "action": "SearchRetailEntities",
            "search_param": text
        })
    }
    useEffect(() => {
        if (searchText) {
            searchRetailer(searchText)
        }
    }, [searchText])
    useEffect(() => {
        if (entitiesActionsApi.data && entitiesActionsApi.data.length) {
            setretailers(entitiesActionsApi.data)
        }
        console.log('entitiesActionsApi.data', entitiesActionsApi.data)
    }, [entitiesActionsApi.data])

    const handleSelectRetailer = (item) => {
        console.log('item', item)
        navigate(`/shopfront/${item.id}`, {
            state: {
                'entity': item
            }
        })
    }


    return (
        <div className='grid grid-cols-1 lg:grid-cols-3 lg:min-w-max'>
            <div></div>
            <div>   <div className="w-full h-[100px] px-8 rounded-2xl flex justify-center items-center bg-gradient-to-tr from-slate-500 to-slate-300 text-white shadow-lg">
                <Input
                    onChange={(e) => handleSearchTextChange(e)}
                    label="Search shop or restaurant by name"
                    isClearable
                    radius="lg"
                    classNames={{
                        label: "text-black/50 dark:text-white/90 text-medium text-center",
                        input: [
                            "bg-white",
                            "text-black/90 dark:text-white/90",
                            "placeholder:text-default-700/50 dark:placeholder:text-white/60",
                            "h-[70px]",
                        ],
                        innerWrapper: "bg-transparent",
                        inputWrapper: [
                            "shadow-xl",
                            "bg-default-200/50",
                            "dark:bg-default/60",
                            "backdrop-blur-xl",
                            "backdrop-saturate-200",
                            "hover:bg-default-200/70",
                            "dark:hover:bg-default/70",
                            "group-data-[focused=true]:bg-default-200/50",
                            "dark:group-data-[focused=true]:bg-default/60",
                            "!cursor-text",
                        ],
                    }}
                    placeholder="Type to search..."
                    startContent={
                        <SearchIcon className="text-black/50 dark:text-white/90 text-slate-400 pointer-events-none flex-shrink-0" />
                    }
                />
            </div>
                <div>
                    {retailers && retailers.map(item =>
                        <Card className='max-w-full mx-1  my-2 cursor-pointer'>
                            <CardHeader onClick={() => handleSelectRetailer(item)} className="justify-between">
                                <div className="flex gap-5 items-center">
                                    <Avatar className="w-20 h-20 text-large" isBordered radius="sm" size="lg" src={item.image ? item.image : ""} name={item.title} />
                                    <div className="flex flex-col gap-1 items-start justify-center">
                                        <h4 className="text-medium font-semibold leading-none text-default-600">{item.title}</h4>

                                    </div>
                                </div>
                            </CardHeader>
                        </Card>)}
                </div></div>
            <div></div>
        </div>
    )
}

export default ShopsList