import React, { useEffect, useState } from 'react'
import FormulationsTable from './FormulationsTable'

import useApi from '../../hooks/useApi'
import { useNavigate } from 'react-router-dom';
import FormulationsFormModal from './FormulationsFormModal';
import formulationsApi from '../../api/drugs/formulationsApi';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Description", uid: "description" },
    { name: "Actions", uid: "actions" },
];


function FormulationsList() {
    const [openEditModal, setopenEditModal] = useState(false)

    const navigate = useNavigate()
    const [formulation, setFormulation] = useState()
    const [formulations, setFormulations] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const formulationsActionsApi = useApi(formulationsApi.formulationsAction)

    const getFormulations = async () => {
        await formulationsActionsApi.request({
            "action": "GetFormulations"

        })
    }
    useEffect(() => {
        setdata(formulations)
    }, [formulations])

    const handleFilter = (e) => {

        console.log('eeeee', e)
        const search_param = e

        if (formulations && formulations.length > 0 && search_param && search_param !== '') {
            setdata(formulations.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(formulations);
        }
    };

    useEffect(() => {
        getFormulations()
    }, [])


    const handleEditAction = (item) => {

        setopenEditModal(true)
        setFormulation(item)
        setmodalTitle(`Edit ${item.tittle}`)

    }

    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new formulation")
        setFormulation(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/formulations/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/formulations/delete/${item.id}`)
    }



    useEffect(() => {

        if (formulationsActionsApi.data && formulationsActionsApi.data.length) {

            setFormulations(formulationsActionsApi.data)
        }
    }, [formulationsActionsApi.data])

    useEffect(() => {
        getFormulations()
    }, [updated])

    return (
        <div>
            {openEditModal && <FormulationsFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} item={formulation} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <FormulationsTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default FormulationsList