import React, { useEffect, useState } from 'react'
import ProductsTable from './ProductsTable'
import useApi from '../../hooks/useApi'
import { useNavigate } from 'react-router-dom';
import ProductsFormModal from './ProductsFormModal';
import productsApi from '../../api/productsApi';
import { Loading } from '../../components';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Long Title", uid: "long_title" },
    { name: "Category", uid: "category_title" },
    { name: "Pack Size", uid: "units_per_pack" },
    { name: "Packaging", uid: "packaging" },
    { name: "Manufacturer", uid: "manufacturer_title" },
    { name: "Actions", uid: "actions" },
];


function ProductsList() {
    const [openEditModal, setopenEditModal] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const navigate = useNavigate()
    const [product, setProduct] = useState()
    const [products, setProducts] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)

    const productsActionsApi = useApi(productsApi.productsAction)

    const getProducts = async () => {
        await productsActionsApi.request({
            "action": "GetAllProducts"

        })
    }


    useEffect(() => {
        getProducts()
    }, [])


    const handleEditAction = (item) => {
      console.log("to edit ", item);
      setUpdated(false);
      setopenEditModal(true);
      setProduct(item);
      setmodalTitle(`${item.title}`);
    };

    const handleAddAction = () => {
      setUpdated(false);
      setopenEditModal(true);
      setmodalTitle("Add new entity");
      setProduct(null);
    };
    const handleDetailsAction = (item) => {
      navigate(`/products/details/${item.id}`, {
        state: {
          item: item,
        },
      });
    };
    const handleDeleteAction = (item) => {
      navigate(`/products/delete/${item.id}`);
    };

    useEffect(() => {
      if (productsActionsApi.data && productsActionsApi.data.length) {
        setProducts(productsActionsApi.data);
      }

      console.log("preparationsActionsApi.data", productsActionsApi.data);
    }, [productsActionsApi.data]);

    useEffect(() => {
      getProducts();
    }, [updated]);

    //Filtering data
    useEffect(() => {
      setdata(products);
    }, [products]);

    const handleFilter = (e) => {
      const search_param = e;

      if (
        products &&
        products.length > 0 &&
        search_param &&
        search_param !== ""
      ) {
        setdata(
          products.filter((x) => x.title.toLowerCase().includes(search_param))
        );
      } else {
        setdata(products);
      }
    };

    return (
      <div>
        {openEditModal && (
          <ProductsFormModal
            ismodalOpen={openEditModal}
            setisModalOpen={setopenEditModal}
            productToEdit={product}
            updated={updated}
            setUpdated={setUpdated}
            modalTitle={modalTitle}
          />
        )}
        {productsActionsApi.loading ? (
          <Loading loading={productsActionsApi.loading} />
        ) : (
          <ProductsTable
            data={data}
            columns={columns}
            editAction={handleEditAction}
            detailsAction={handleDetailsAction}
            deleteAction={handleDeleteAction}
            addAction={handleAddAction}
            handleFilter={handleFilter}
          />
        )}
      </div>
    );
}

export default ProductsList