import React, { useEffect, useState } from 'react'
import DrugSubClassesTable from './DrugSubClassesTable'
import useApi from '../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import DrugSubClassesFormModal from './DrugSubClassesFormModal';
import drugClassesApi from '../../api/drugs/drugClassesApi';
import drugSubClassesApi from '../../api/drugs/drugSubClassesApi';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Description", uid: "description" },
    { name: "Parent Drug Class", uid: "drug_class_title" },
    { name: "Actions", uid: "actions" },
];


function DrugSubClassesList() {
    const [openEditModal, setopenEditModal] = useState(false)

    const navigate = useNavigate()
    const [drugSubClass, setDrugSubClass] = useState()
    const [drugSubClasses, setDrugSubClasses] = useState([])
    const [data, setdata] = useState(drugSubClass ? drugSubClass : [])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const drugSubClassesActionsApi = useApi(drugSubClassesApi.drugSubClassesAction)


    const getDrugClasses = async () => {
        await drugSubClassesActionsApi.request({
            "action": "GetDrugSubClasses"

        })
    }

    useEffect(() => {
        getDrugClasses()
    }, [])


    const handleEditAction = (item) => {
        console.log('tit', item)
        setopenEditModal(true)
        setDrugSubClass(item)
        setmodalTitle(`${item.title}`)

    }

    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new drug sub class")
        setDrugSubClass(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/drugsubclasses/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {

        navigate(`/drugsubclasses/delete/${item.id}`)
    }


    useEffect(() => {

        if (drugSubClassesActionsApi.data && drugSubClassesActionsApi.data.length) {

            setDrugSubClasses(drugSubClassesActionsApi.data)
        }
    }, [drugSubClassesActionsApi.data])

    useEffect(() => {
        getDrugClasses()
    }, [updated])

    //Filtering data
    useEffect(() => {
        if (drugSubClasses.length > 0) {

            setdata(drugSubClasses)

        }

    }, [drugSubClasses])


    const handleFilter = (e) => {
        const search_param = e

        if (drugSubClasses && drugSubClasses.length > 0 && search_param && search_param !== '') {
            setdata(drugSubClasses.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(drugSubClasses);
        }

    };

    return (
        <div>
            {openEditModal && <DrugSubClassesFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} item={drugSubClass} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <DrugSubClassesTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default DrugSubClassesList