import React, { useEffect, useState } from 'react'
import DrugClassesTable from './DrugClassesTable'
import useApi from '../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import DrugClassesFormModal from './DrugClassesFormModal';
import genericsApi from '../../api/drugs/genericsApi';
import drugClassesApi from '../../api/drugs/drugClassesApi';
import { Loading } from '../../components';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Description", uid: "description" },
    { name: "Actions", uid: "actions" },
];


function DrugClassesList() {
    const [openEditModal, setopenEditModal] = useState(false)

    const navigate = useNavigate()
    const [drugClass, setDrugClass] = useState()
    const [drugClasses, setDrugClasses] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const drugClassesActionsApi = useApi(drugClassesApi.drugClassesAction)


    const getDrugClasses = async () => {
        await drugClassesActionsApi.request({
            "action": "GetDrugClasses"

        })
    }

    useEffect(() => {
        getDrugClasses()
    }, [])


    const handleEditAction = (item) => {
        console.log('tit', item)
        setopenEditModal(true)
        setDrugClass(item)
        setmodalTitle(`${item.title}`)

    }

    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new drug class")
        setDrugClass(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/drugclasses/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {

        navigate(`/drugclasses/delete/${item.id}`)
    }


    useEffect(() => {

        if (drugClassesActionsApi.data && drugClassesActionsApi.data.length) {

            setDrugClasses(drugClassesActionsApi.data)
        }
    }, [drugClassesActionsApi.data])

    // useEffect(() => {
    //     getDrugClasses()
    // }, [updated])

    //Filtering data
    useEffect(() => {
        setdata(drugClasses)
    }, [drugClasses])


    const handleFilter = (e) => {

        console.log('eeeee', e)
        const search_param = e

        if (drugClasses && drugClasses.length > 0 && search_param && search_param !== '') {
            setdata(drugClasses.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(drugClasses);
        }

    };

    return (
        <div>
            {openEditModal && <DrugClassesFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} item={drugClass} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            {drugClassesActionsApi.loading ? <Loading loading={drugClassesActionsApi.loading} /> : <DrugClassesTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />}
        </div>
    )
}

export default DrugClassesList