import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea, Select, SelectItem } from "@heroui/react";
import { Loading } from '../../components';
import { useFormik } from "formik";
import useApi from "../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import bodySystemsApi from "../../api/drugs/bodySystemsApi";
import makeAnimated from "react-select/animated"
import CreateSelect from "react-select/creatable";
import drugClassesApi from "../../api/drugs/drugClassesApi";
import genericsApi from "../../api/drugs/genericsApi";
import drugSubClassesApi from "../../api/drugs/drugSubClassesApi";


export default function GenericsFormModal({ openEditModal, setopenEditModal, item, updated, setUpdated, modalTitle }) {
    // const { isOpen, onOpen, onOpenChange } = useDisclosure();
    const animatedComponent = makeAnimated();
    const [generic, setGeneric] = useState(item ? item : null)
    const [drugSubClasses, setdrugSubClasses] = useState([])
    const [errors, setErrors] = useState();



    //Retrieve drug classes
    const [drugClasses, setDrugClasses] = useState([])
    const drugClassesActionsApi = useApi(drugClassesApi.drugClassesAction

    )

    const getDrugClasses = async () => {
        await drugClassesActionsApi.request({
            "action": "GetDrugClasses"

        })
    }

    useEffect(() => {
        getDrugClasses()
    }, [])

    useEffect(() => {

        if (drugClassesActionsApi.data && drugClassesActionsApi.data.length) {

            setDrugClasses(drugClassesActionsApi.data.map((i) => ({ label: i.title, value: i.id })))
        }
    }, [drugClassesActionsApi.data])



    const genericsActionsApi = useApi(genericsApi.genericsAction);

    const handleGenericsAction = async (data) => {
        const result = await genericsActionsApi.request(data);

        if (result.ok) {
            setUpdated(true)
            setopenEditModal(false)
        } else {
            setErrors(result.data.errors)
        }

    }

    useEffect(() => { }, [generic])

    useEffect(() => {

        if (genericsActionsApi.data) {
            if (genericsActionsApi.data.category) {
                setGeneric(genericsActionsApi.data.category)
            }
        }
    }, [genericsActionsApi.data])

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    const formik = useFormik({
        initialValues: {
            title: generic ? generic.title : '',
            description: generic ? generic.description : '',
            drug_class: generic ? { 'label': generic.drug_class_title, 'value': generic.drug_class_id } : '',
            drug_sub_class: generic ? { 'label': generic.drug_sub_class_title, 'value': generic.drug_sub_class_id } : ''
        },

        validationSchema: Yup.object({
            title: Yup.string()
                .min(3, "Must be 15 characters or more")
                .required("Title is required"),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)
            setErrors([])

            if (item) {


                handleGenericsAction({
                    "action": "UpdateGeneric",
                    "generic_details": {
                        "id": generic.id,
                        "title": values.title,
                        "description": values.description ? values.description : "",
                        "drug_class": values.drug_class.value,
                        "drug_sub_class": values.drug_sub_class ? values.drug_sub_class.value : null
                    }
                })
            } else {
                handleGenericsAction({
                    "action": "CreateGeneric",
                    "generic_details": {
                        "title": values.title,
                        "description": values.description,
                        "drug_class": values.drug_class.value,
                        "drug_sub_class": values.drug_sub_class.value
                    }
                })
            }




            resetForm();
        },
    });

    const drugSubClassesActionsApi = useApi(drugSubClassesApi.drugSubClassesAction)

    const getSubclassesForDrugClass = async (value) => {

        setdrugSubClasses([])

        const result = await drugSubClassesActionsApi.request({
            "action": "GetDrugSubClassesForDrugClass",
            "drug_class_id": value.value
        })




    }

    const handleSelectDrugClass = (value) => {
        if (!value == "") {
            setdrugSubClasses([])
            formik.setFieldValue("drug_class", value)
            getSubclassesForDrugClass(value)
        }

    }

    useEffect(() => {

        if (drugSubClassesActionsApi.data) {
            if (drugSubClassesActionsApi.data.length) {
                setdrugSubClasses(drugSubClassesActionsApi.data.map((i) => ({ label: i.title, value: i.id })))
            }
        }
    }, [drugSubClassesActionsApi.data])

    useEffect(() => { }, [drugSubClasses])


    return (
        <>
            {drugSubClassesActionsApi.loading ? <Loading /> : <Modal
                isOpen={openEditModal}
                placement="center"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            {genericsActionsApi.loading ? <Loading /> : <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1">{modalTitle}</ModalHeader>
                                <ModalBody>
                                    <Input
                                        id="title"
                                        name="title"
                                        autoFocus
                                        label="Title"
                                        placeholder="Enter title"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.title}
                                        value={formik.values.title}
                                    />

                                    <div>
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="drug_class"
                                            key="drug_class"
                                            name="drug_class"
                                            components={animatedComponent}
                                            placeholder="Select drug class"
                                            isClearable
                                            value={formik.values.drug_class}
                                            onChange={(value) => handleSelectDrugClass(value)}
                                            options={drugClasses}
                                        />
                                        {formik.touched.drug_class && formik.errors.drug_class ? (
                                            <p color="danger">{formik.errors.drug_class}</p>
                                        ) : null}
                                    </div>
                                    <div>
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="drug_sub_class"
                                            key="drug_sub_class"
                                            name="drug_sub_class"
                                            components={animatedComponent}
                                            placeholder="Select drug sub class"
                                            isClearable
                                            value={formik.values.drug_sub_class}
                                            onChange={(value) => formik.setFieldValue("drug_sub_class", value)}
                                            options={drugSubClasses}
                                        />
                                        {formik.touched.drug_sub_class && formik.errors.drug_sub_class ? (
                                            <p color="danger">{formik.errors.drug_sub_class}</p>
                                        ) : null}
                                    </div>

                                    <Textarea
                                        id="description"
                                        key="description"
                                        name="description"
                                        label="Description"
                                        placeholder="Type description"
                                        variant="bordered"
                                        defaultValue={formik.values.description}
                                        value={formik.values.description}
                                        onBlur={formik.handleBlur}
                                        onChange={formik.handleChange}
                                    />


                                </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenEditModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>}


                        </>
                    )}
                </ModalContent>
            </Modal>}
        </>
    );
}
