import React, { useEffect, useState } from 'react'
import RolesTable from "./RolesTable";
import useApi from "../../../hooks/useApi";
import { useNavigate } from "react-router-dom";
import { getLoggedInUser } from "../../../helpers/authUtils";
import RolesFormModal from "./RolesFormModal";
import rolesApi from "../../../api/rolesApi";

const columns = [
  { name: "Title", uid: "title" },
  { name: "Description", uid: "description" },

  { name: "Actions", uid: "actions" },
];

function RolesList() {
  const [openRoleFormModal, setopenRoleFormModal] = useState(false);
  const navigate = useNavigate();
  const [role, setRole] = useState();
  const [roles, setRoles] = useState([]);
  const [data, setdata] = useState([]);
  const [updated, setUpdated] = useState(false);
  const [modalTitle, setmodalTitle] = useState("");
  const rolesActionsApi = useApi(rolesApi.rolesAction);

  const [user, setUser] = useState();

  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);

  const getEntityRoles = async () => {
    setRoles([]);
    await rolesActionsApi.request({
      action: "GetEntityRoles",
    });
  };

  useEffect(() => {
    getEntityRoles();
  }, []);

  useEffect(() => {
    if (updated === true) {
      getEntityRoles();
    }
  }, [updated]);

  useEffect(() => {
    getEntityRoles();
  }, [openRoleFormModal]);

  const handleEditAction = (item) => {
    setopenRoleFormModal(true);

    setUpdated(false);

    setRole(item);
    setmodalTitle(`${item.title}`);
  };

  const handleAddAction = () => {
    setopenRoleFormModal(true);

    setUpdated(false);

    setmodalTitle("Add new role");
    setRole(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/retailers/roles/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    navigate(`/retailers/roles/delete/${item.id}`);
  };

  useEffect(() => {
    if (rolesActionsApi.data && rolesActionsApi.data.length) {
      setRoles(rolesActionsApi.data);
    }

    console.log("entitiesActionsApi.data", rolesActionsApi.data);
  }, [rolesActionsApi.data]);

  useEffect(() => {}, [openRoleFormModal]);

  //Filtering data
  useEffect(() => {
    setdata(roles);
  }, [roles]);

  const handleFilter = (e) => {
    const search_param = e;

    if (roles && roles.length > 0 && search_param && search_param !== "") {
      setdata(
        roles.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(roles);
    }
  };

  return (
    <div>
      {openRoleFormModal && (
        <RolesFormModal
          ismodalOpen={openRoleFormModal}
          setisModalOpen={setopenRoleFormModal}
          role={role}
          updated={updated}
          setUpdated={setUpdated}
          modalTitle={modalTitle}
        />
      )}
      <RolesTable
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default RolesList