import React, { useEffect, useState } from 'react'
import FrequenciesTable from './FrequenciesTable'

import useApi from '../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import FrequenciesFormModal from './FrequenciesFormModal';
import frequenciesApi from '../../api/drugs/frequenciesApi';
import { Loading } from '../../components';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Description", uid: "description" },
    { name: "Actions", uid: "actions" },
];


function FrequenciesList() {
    const [openEditModal, setopenEditModal] = useState(false)

    const navigate = useNavigate()
    const [frequency, setFrequency] = useState()
    const [frequencies, setFrequencies] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const frquenciesActionsApi = useApi(frequenciesApi.frequenciesAction)

    const getFrequencies = async () => {
        await frquenciesActionsApi.request({
            "action": "GetFrequencies"

        })
    }


    useEffect(() => {
        getFrequencies()
    }, [])


    const handleEditAction = (item) => {

        setopenEditModal(true)
        setFrequency(item)
        setmodalTitle(`Edit ${item.tittle}`)

    }

    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new body system")
        setFrequency(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/systems/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/systems/delete/${item.id}`)
    }


    useEffect(() => {

        if (frquenciesActionsApi.data && frquenciesActionsApi.data.length) {

            setFrequencies(frquenciesActionsApi.data)
        }
    }, [frquenciesActionsApi.data])

    useEffect(() => {
        getFrequencies()
    }, [updated])


    //Filtering data
    useEffect(() => {
        setdata(frequencies)
    }, [frequencies])


    const handleFilter = (e) => {
        const search_param = e
        if (frequencies && frequencies.length > 0 && search_param && search_param !== '') {
            setdata(frequencies.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(frequencies);
        }

    };

    return frquenciesActionsApi.loading ? <Loading loading={frequenciesApi.loading} /> : (
        <div>
            {openEditModal && <FrequenciesFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} item={frequency} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <FrequenciesTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default FrequenciesList