import React, { useCallback, useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectAsyncSelect,
  CustomSelectReactSelect,
  CustomSwitch,
} from "../../../../components";
import { useFormik } from "formik";
import useApi from "../../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import employeesApi from "../../../../api/employees/employeesApi";
import { Modal } from "antd";
import advertsApi from "../../../../api/employees/advertsApi";
import departmentsApi from "../../../../api/departmentsApi";
import designationsApi from "../../../../api/employees/designationsApi";
import rolesApi from "../../../../api/rolesApi";
import entitiesApi from "../../../../api/entitiesApi";
import { useStateContext } from "../../../../contexts/ContextProvider";
import dayjs from "dayjs";
import usersApi from "../../../../api/usersApi";
import cadresApi from "../../../../api/cadresApi";
import tenures from "../../../../data/tenures";

export default function DesignationsFormModal({
  openEditModal,
  setopenEditModal,
  designation,
  modalTitle = "Create new designation",
  updated,
  setUpdated,
  user,
}) {




  const { dangerColor, currentColor } = useStateContext();



  const [errors, setErrors] = useState();

  useEffect(() => { }, [designation]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);






  const handleOk = () => {
    setopenEditModal(false);
  };
  const handleCancel = () => {
    setopenEditModal(false);
  };

  const designationsActionsApi = useApi(designationsApi.designationsAction);

  const handleDesignationAction = async (data) => {
    const result = await designationsActionsApi.request(data);

    if (result.ok) {
      setUpdated(true)
      setopenEditModal(setUpdated)
    } else {
      setUpdated(false)
    }

  }



  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const formik = useFormik({
    initialValues: {
      title: designation ? designation.title : '',
      total_slots: designation ? designation.total_slots : '',
      duration_in_months: designation ? designation.duration_in_months : '',
      description: designation ? designation.description : '',
      cadre: designation ? { 'label': designation.cadre_title, 'value': designation.cadre } : null,
      tenure: designation ? { 'label': designation.tenure, 'value': designation.tenure } : null,
    },

    validationSchema: Yup.object({
      title: Yup.string()
        .min(3, "Must be 15 characters or more")
        .required("Title is required"),
      cadre: Yup.object().required().label('Cadre'),
      total_slots: Yup.string().min(1).required().label('Available slots'),
      duration_in_months: Yup.number().min(1).required().label('Duration'),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log('VALZ', values)
      setErrors([])

      if (designation) {

        handleDesignationAction({
          "action": "UpdateDesignation",
          "designation_details": {
            "id": designation.id,
            "title": values.title,
            "description": values.description ? values.description : '',
            "cadre": values.cadre.value,
            "tenure": values.tenure.value,
            "total_slots": values.total_slots,
            "duration_in_months": values.duration_in_months,
          }
        })
      } else {
        handleDesignationAction({
          "action": "CreateDesignation",
          "designation_details": {
            "description": values.description,
            "title": values.title,
            "cadre": values.cadre.value,
            "total_slots": values.total_slots,
            "tenure": values.tenure.value,
            "duration_in_months": values.duration_in_months,


          }

        })
      }




      // resetForm();
    },
  });


  //Retrieve clusters
  const [cadres, setCadres] = useState([])
  const cadresActionsApi = useApi(cadresApi.cadresAction)
  const getClusters = async () => {
    await cadresActionsApi.request({
      "action": "GetCadres"

    })
  }

  useEffect(() => {
    getClusters()
  }, [])

  useEffect(() => {

    if (cadresActionsApi.data && cadresActionsApi.data.length) {

      setCadres(cadresActionsApi.data.map((i) => ({ label: i.title, value: i.id })))
    }

    console.log
      ('cadresActionsApi.data', cadresActionsApi.data)
  }, [cadresActionsApi.data])




  return (
    <div className="w-full">
      <Modal
        width={600}
        className="w-full text-center"
        title={modalTitle}
        open={openEditModal}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        {errors && errors.length ? (
          <div>
            {errors.map((x) => {
              return <p className="text-red-400 font-bold text-medium">{x}</p>;
            })}
          </div>
        ) : (
          <div></div>
        )}

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className="grid grid-cols-1 gap-2  items-center w-full my-7"
        >
        <CustomFormItem
        touched={formik.touched.cadre}
        error={formik.errors.cadre}
      >
        <CustomSelectReactSelect
          className="text-start"
          name="cadre"
          id="cadre"
          label="Select cadre"
          size="large"
          onChange={(value) => formik.setFieldValue("cadre", value)}
          value={formik.values.cadre}
          placeholder="Select cadre"
          options={cadres}
        />
      </CustomFormItem>

      <CustomFormItem
        touched={formik.touched.tenure}
        error={formik.errors.tenure}
      >
        <CustomSelectReactSelect
          className="text-start"
          name="tenure"
          id="tenure"
          label="Select tenure"
          size="large"
          onChange={(value) => formik.setFieldValue("tenure", value)}
          value={formik.values.tenure}
          placeholder="Select tenure"
          options={tenures}
        />
      </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
          >
            <CustomInput
              required={true}
              id="title"
              name="title"
              onChange={formik.handleChange}
              placeholder="Enter designation title"
              size="large"
              type="text"
              value={formik.values.title}
              label="Enter designation title"
            />
          </CustomFormItem>
          <CustomFormItem
            touched={formik.touched.duration_in_months}
            error={formik.errors.duration_in_months}
          >
            <CustomInput
              required={true}
              id="duration_in_months"
              name="duration_in_months"
              onChange={formik.handleChange}
              placeholder="Enter duration in months"
              size="large"
              type="number"
              value={formik.values.duration_in_months}
              label="Enter duration in months"
            />
          </CustomFormItem>
          <CustomFormItem
          touched={formik.touched.total_slots}
          error={formik.errors.total_slots}
        >
          <CustomInput
            required={true}
            id="total_slots"
            name="total_slots"
            onChange={formik.handleChange}
            placeholder="Enter total slots"
            size="large"
            type="number"
            value={formik.values.total_slots}
            label="Enter total slots"
          />
        </CustomFormItem>



         

      

       


    

       

 

          <div className="w-full items-center mt-2">
            <Button
              style={{ background: currentColor }}
              className="w-36 rounded-md"
              color="primary"
              type="submit"
            >
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
