import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea } from "@heroui/react";
import { Loading } from '../../../components';
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import makeAnimated from "react-select/animated"
import CreateSelect from "react-select/creatable";
import { ToastContainer, toast } from "react-toastify";
import advertsApi from "../../../api/employees/advertsApi";
import designationsApi from "../../../api/employees/designationsApi";
import { DatePicker, Space } from 'antd';
import locale from 'antd/es/date-picker/locale/en_US';
import dayjs from 'dayjs';
import 'dayjs/locale/en-gb';


export default function AdvertsFormModal({ openEditModal, setopenEditModal, item, updated, setUpdated, modalTitle }) {
    const moment = require('moment')
    const animatedComponent = makeAnimated();
    const [advert, setAdvert] = useState(item ? item : null)

    const [errors, setErrors] = useState();
    const advertsActionsApi = useApi(advertsApi.advertsAction);

    const handleAdvertAction = async (data) => {
        const result = await advertsActionsApi.request(data);

        if (result.ok) {
            setUpdated(true)
            setopenEditModal(setUpdated)
        } else {
            setUpdated(false)
        }

    }

    const handleClosingDateChange = (date, dateString) => {
        formik.setFieldValue('closes', dateString
        )

    }

    useEffect(() => { }, [advert])

    useEffect(() => {

        if (advertsActionsApi.data) {
            if (advertsActionsApi.data.category) {
                setAdvert(advertsActionsApi.data.category)
            }
        }
    }, [advertsActionsApi.data])

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);



    //Retrieve designations
    const [designations, setDesignations] = useState([])
    const designationsActionsApi = useApi(designationsApi.designationsAction)
    const getDesignations = async () => {
        await designationsActionsApi.request({
            "action": "EntityDesignations"

        })
    }
    useEffect(() => {
        getDesignations()
    }, [])

    useEffect(() => {

        if (designationsActionsApi.data && designationsActionsApi.data.length) {

            setDesignations(designationsActionsApi.data.map((i) => ({ label: i.title, value: i.id })))
        }
        console.log('designations', designations)
    }, [designationsActionsApi.data])


    const formik = useFormik({
        initialValues: {
            closes: advert ? advert.closes : moment(new Date()).format("YYYY-MM-DD"),
            title: advert ? advert.title : '',
            vacancies: advert ? advert.vacancies : '',
            designation: advert ? { 'label': advert.designation_title, 'value': advert.designation } : null,
            description: advert ? advert.description : ''
        },

        validationSchema: Yup.object({
            title: Yup.string()
                .min(3, "Must be 15 characters or more")
                .required("Title is required"),
            designation: Yup.object().required()
                .label("Designation"),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)
            setErrors([])

            if (item) {

                handleAdvertAction({
                    "action": "UpdateAdvert",
                    "advert_details": {
                        "id": item.id,
                        "title": values.title,
                        "vacancies": values.vacancies,
                        "designation": values.designation.value,
                        "closes": values.closes,
                        "description": values.description,

                    }
                })
            } else {
                handleAdvertAction({
                    "action": "CreateAdvert",
                    "advert_details": {
                        "title": values.title,
                        "vacancies": values.vacancies,
                        "designation": values.designation.value,
                        "closes": values.closes,
                        "description": values.description,

                    }
                })
            }




            resetForm();
        },
    });


    return (
        <>

            <Modal
                isOpen={openEditModal}
                placement="center"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            {advertsActionsApi.loading ? <Loading /> : <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1">{modalTitle}</ModalHeader>
                                <ModalBody>
                                    <Input
                                        id="title"
                                        name="title"
                                        autoFocus
                                        label="Title"
                                        placeholder="Enter title"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.title}
                                        value={formik.values.title}
                                        color={formik.errors.title ? "danger" : "grey"}
                                        errorMessage={formik.errors.title}
                                    />
                                    <Input
                                        id="vacancies"
                                        name="vacancies"
                                        autoFocus
                                        label="Number of vacancies advertised"
                                        placeholder="Enter vacancies advertised"
                                        variant="bordered"
                                        type="number"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.vacancies}
                                        value={formik.values.vacancies}
                                        color={formik.errors.vacancies ? "danger" : "grey"}
                                        errorMessage={formik.errors.vacancies}
                                    />

                                    <div>
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="designation"
                                            key="designation"
                                            name="designation"
                                            components={animatedComponent}
                                            placeholder="Select  designation"
                                            isClearable
                                            value={formik.values.designation}
                                            onChange={(value) => formik.setFieldValue("designation", value)}
                                            options={designations}
                                        />
                                        {formik.touched.designation && formik.errors.designation ? (
                                            <p className="text-red-500 text-sm">{formik.errors.designation}</p>
                                        ) : null}
                                    </div>

                                    <Space direction="vertical">

                                        <DatePicker locale={locale} defaultValue={dayjs(formik.values.closes, 'YYYY-MM-DD')} id="closes" name="closes" placeholder="Select applications  closing date" style={{
                                            height: 60,
                                            borderRadius: 15,
                                            borderColor: 'gray',
                                        }} className="w-full h-11" onChange={handleClosingDateChange} />
                                        {formik.errors.closes ? (
                                            <p className="text-red-500 text-sm">{formik.errors.closes}</p>
                                        ) : null}
                                    </Space>

                                    <Textarea
                                        id="description"
                                        key="description"
                                        name="description"
                                        label="Description"
                                        placeholder="Type description"
                                        variant="bordered"
                                        defaultValue={formik.values.description}
                                        value={formik.values.description}
                                        onBlur={formik.handleBlur}
                                        onChange={formik.handleChange}
                                    />
                                </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenEditModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>}


                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
