import React, { useEffect, useState } from 'react'
import InventoryTable from './InventoryTable'
import { useNavigate } from 'react-router-dom';
import { getLoggedInUser } from '../../../helpers/authUtils';
import InventoryFormModal from './InventoryFormModal';
import { Loading } from '../../../components';
import { useDispatch, useSelector } from 'react-redux';
import { getRetailerReceipts } from '../../../redux/retailers/receipts/actions';
import { toast, ToastContainer } from "react-toastify";

const columns = [
  { name: "Title", uid: "title" },
  { name: "Unit Qty", uid: "current_unit_quantity" },
  { name: "Buying Price", uid: "unit_buying_price" },
  { name: "Selling Price", uid: "unit_selling_price" },
  { name: "Price Discount", uid: "unit_price_discount" },
  { name: "Final Unit Price", uid: "final_unit_selling_price" },
  { name: "Mfd", uid: "manufacture_date" },
  { name: "Expiry", uid: "expiry_date" },
  { name: "Expiry Status", uid: "expiry_status" },
  { name: "Actions", uid: "actions" },
];

function InventoryList() {
  const [openRetailerReceiptFormModal, setopenRetailerReceiptFormModal] =
    useState(false);
  const navigate = useNavigate();
  const [retailerReceipt, setRetailerReceipt] = useState();
  // const [retailerReceipts, setRetailerReceipts] = useState([])

  const [updated, setUpdated] = useState(false);
  const [itemsToDisplay, setitemsToDisplay] = useState(50);
  const [modalTitle, setmodalTitle] = useState("");

  const retailerReceipts = useSelector(
    (state) => state.RetailerReceipts.retailerReceipts
  );
  const loading = useSelector((state) => state.RetailerReceipts.loading);
  const errors = useSelector((state) => state.RetailerReceipts.errors);

  const [data, setdata] = useState(retailerReceipts);

  const [user, setUser] = useState();

  const dispatch = useDispatch();

  useEffect(() => {
    setUser(getLoggedInUser());
  }, []);

  useEffect(() => {
    dispatch(
      getRetailerReceipts({
        action: "GetRetailerReceipts",
      })
    );
  }, []);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((error) => {
        return toast.error(error);
      });
    }
  }, [errors]);

  // const retailerReceiptsActionsApi = useApi(retailerReceiptsApi.retailerReceiptsActionAdmin)
  // const getEntityRetailerReceipts = async (user) => {
  //     setRetailerReceipts([])
  //     await retailerReceiptsActionsApi.request({
  //         "action": "GetRetailerReceipts"
  //     })
  // }

  // useEffect(() => {
  //     getEntityRetailerReceipts()
  // }, [])

  // useEffect(() => {
  //     getEntityRetailerReceipts()
  // }, [openRetailerReceiptFormModal])

  // useEffect(() => {

  //     if (retailerReceiptsActionsApi.data && retailerReceiptsActionsApi.data.length) {

  //         setRetailerReceipts(retailerReceiptsActionsApi.data)
  //     }

  //     console.log('entitiesActionsApi.data', retailerReceiptsActionsApi.data)
  // }, [retailerReceiptsActionsApi.data])

  const handleEditAction = (item) => {
    setopenRetailerReceiptFormModal(true);

    // setUpdated(false)

    setRetailerReceipt(item);
    setmodalTitle(`${item.title}`);
  };

  const handleAddAction = () => {
    setopenRetailerReceiptFormModal(true);

    setUpdated(false);

    setmodalTitle("Add new inventory item");
    setRetailerReceipt(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/retailers/inventory/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    navigate(`/retailers/inventory/delete/${item.id}`);
  };

  useEffect(() => {}, [openRetailerReceiptFormModal]);

  // //Filtering data
  useEffect(() => {
    setdata(retailerReceipts);
  }, [retailerReceipts]);

  const handleFilter = (e) => {
    console.log("filter", e);

    const search_param = e;

    if (search_param && search_param !== "") {
      setdata(
        retailerReceipts.filter((x) =>
          x.title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(retailerReceipts);
      console.log("receipts", retailerReceipts);
      // dispatch()
    }
  };

  return loading ? (
    <Loading loading={loading} />
  ) : (
      <div className='mt-14 md:mt-0'>
      {openRetailerReceiptFormModal && (
        <InventoryFormModal
          ismodalOpen={openRetailerReceiptFormModal}
          setisModalOpen={setopenRetailerReceiptFormModal}
          inventoryToEdit={retailerReceipt}
          updated={updated}
          setUpdated={setUpdated}
          modalTitle={modalTitle}
        />
      )}
      <InventoryTable
          title={`Inventory List (${data.length})`}
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
        itemsToDisplay={itemsToDisplay}
        setitemsToDisplay={setitemsToDisplay}
      />

      <ToastContainer theme="colored" position="bottom-center" />
    </div>
  );
}

export default InventoryList