import React, { useEffect, useState } from "react";
import { useLocation, useParams } from "react-router-dom";
import { Button, Divider, User } from "@heroui/react";
import useApi from "../../hooks/useApi";
import { usersAction, usersActionAdmin } from "../../redux/users/users/actions";
import usersApi from "../../api/usersApi";
import PictureUploadModal from "./PictureUploadModal";
import DocumentUploadModal from "./DocumentUploadModal";
import ViewDocumentModal from "./ViewDocumentModal";
import { ToastContainer, toast } from "react-toastify";
import { Loading } from "../../components";

function UserDetails() {
  const location = useLocation();
  console.log("location", location);

  const [item, setitem] = useState(
    location.state.item ? location.state.item : null
  );
  // console.log('category_id', category)

  const usersActionsApi = useApi(usersApi.usersAdminAction);
  const [profile, setProfile] = useState();
  const [openUploadPictureModal, setopenUploadPictureModal] = useState(false);
  const [openUploadDocumentModal, setopenUploadDocumentModal] = useState(false);
  const [openViewDocumentModal, setopenViewDocumentModal] = useState(false);
  const [selectedDocument, setselectedDocument] = useState();
  const [errors, setErrors] = useState([]);

  useEffect(() => {
    getUserProfile();
  }, [openViewDocumentModal]);
  const getUserProfile = async () => {
    await usersActionsApi.request({
      action: "GetUserDetailsById",
      user: item.id,
    });
  };
  useEffect(() => {
    getUserProfile();
  }, []);
  useEffect(() => {
    if (usersActionsApi.data) {
      if (usersActionsApi.data.user) {
        setProfile(usersActionsApi.data.user);
      }
    }

    console.log("usersActionsApi.data", usersActionsApi.data);
  }, [usersActionsApi.data]);

  const handleSelectDocument = (document) => {
    setopenViewDocumentModal(true);
    setselectedDocument(document);
  };

  const verifyUserApi = useApi(usersApi.usersAction);

  const handleVerifyUser = async (profile) => {
    await verifyUserApi.request({
      action: "VerifyUser",
      user: profile.id,
    });
  };

  useEffect(() => {
    if (verifyUserApi.data) {
      if (verifyUserApi.data.user) {
        setProfile(verifyUserApi.data.user);
      }

      if (verifyUserApi.data.errors) {
        setErrors(verifyUserApi.data.errors);
      }
    }

    console.log("verifyUserApi.data", verifyUserApi.data);
  }, [verifyUserApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  return usersActionsApi.loading ? (
    <Loading loading={usersActionsApi.loading} />
  ) : profile ? (
    <div className="w-full md:grid-cols-2 gap-x-3 mt-16 sm:mt-0 grid grid-cols-1">
      <ToastContainer position="bottom-center" theme="colored" />
      <div>
        <User
          avatarProps={{
            radius: "lg",
            src:
              profile.images && profile.images[0]
                ? profile.images[0].image
                : null,
          }}
          description={profile.email}
          name={`${profile.first_name} ${
            profile.middle_name ? profile.middle_name : ""
          } ${profile.last_name}`}
        >
          {profile.email}
        </User>
        <Divider className="mt-5" />
      </div>

      <div className="space-y-3 p-x-2">
        <h4 className="text-medium font-medium ">Gender</h4>
        <p className="text-small text-default-400">
          {profile && profile.gender
            ? profile.gender
            : "No description availabe"}
        </p>
        <Divider className="mt-5" />
      </div>
      <div className="space-y-3">
        <h4 className="text-medium font-medium ">Date of birth</h4>
        <p className="text-small text-default-400">
          {profile && profile.date_of_birth
            ? profile.date_of_birth
            : "No description availabe"}
        </p>
        <Divider className="mt-5" />
      </div>
      <div className="space-y-3">
        <h4 className="text-medium font-medium ">Date registered</h4>
        <p className="text-small text-default-400">
          {profile && profile.created_at
            ? profile.created_at
            : "No description availabe"}
        </p>
        <Divider className="mt-5" />
      </div>
      <div className="space-y-3">
        <h4 className="text-medium font-medium ">Current entity</h4>
        <p className="text-small text-default-400">
          {profile && profile.entity_title
            ? profile.entity_title
            : "No entity details availabe"}
        </p>
        <Divider className="mt-5" />
      </div>
      <div className="space-y-3">
        <h4 className="text-medium font-medium ">Country</h4>
        <p className="text-small text-default-400">
          {profile && profile.country_title
            ? profile.country_title
            : "No entity details availabe"}
        </p>
        <Divider className="mt-5" />
      </div>
      <div className="space-y-3">
        <h4 className="text-medium font-medium ">Profile pictures</h4>
        {profile.images && profile.images.length ? (
          <div className=" grid grid-cols-4">
            {profile.images.map((x) => (
              <div className="mb-4">
                <img
                  style={{
                    width: 100,
                  }}
                  src={x.image}
                  className="h-auto max-w-full rounded-lg shadow-md"
                  alt=""
                />
              </div>
            ))}
          </div>
        ) : (
          <p className="text-small text-default-400"> No images uploaded</p>
        )}
        {/* <Button color='primary' onPress={() => setopenUploadPictureModal(true)}>Upload pictures</Button> */}
        <Divider className="mt-5" />
      </div>

      <div className="space-y-3">
        <h4 className="text-medium font-medium ">KYC Documents</h4>
        {profile.documents && profile.documents.length ? (
          <div className=" grid grid-cols-4">
            {profile.documents.map((x) => (
              <div className="mb-4">
                <img
                  onClick={() => handleSelectDocument(x)}
                  style={{ width: 60 }}
                  src={x.document}
                  className="h-auto min-w-sm w-4 rounded-lg"
                  alt=""
                />
              </div>
            ))}
          </div>
        ) : (
          <p className="text-small text-default-400"> No documents uploaded</p>
        )}
        {/* <Button color='primary' onPress={() => setopenUploadDocumentModal(true)}>Upload documents</Button> */}
        <Divider className="mt-5" />
      </div>
      <div className="space-y-3">
        <h4 className="text-medium font-medium ">Collection Wallets</h4>
        {profile.accounts && profile.accounts.length ? (
          <div className=" grid grid-cols-2 gap-2">
            {profile.accounts.map((x) => (
              <div className="mb-4 shadow-md my-2">
                <div>
                  {" "}
                  <p>
                    <span>Number: </span>
                    <span>{x.accountNo}</span>
                  </p>
                </div>
                <div>
                  {" "}
                  <p>
                    <span>Name: </span>
                    <span>{x.name}</span>
                  </p>
                </div>
                <div>
                  {" "}
                  <p>
                    <span>Balance: </span>
                    <span>{x.currentBalance.toString()}</span>
                  </p>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p className="text-small text-default-400"> No collection account</p>
        )}
        {/* <Button color='primary' onPress={() => setopenUploadDocumentModal(true)}>Upload documents</Button> */}
        <Divider className="mt-5" />
      </div>

      <div className="space-y-3">
        <h4 className="text-medium font-medium ">Profile verifiction</h4>
        <p className="text-small text-default-400">
          {profile && profile.is_verified === "true"
            ? "Verified"
            : "Not verified"}
        </p>
        {profile.is_verified === "false" &&
        profile.iprs_verified === "false" ? (
          <Button color="primary" onClick={() => handleVerifyUser(profile)}>
            Verify
          </Button>
        ) : (
          <div></div>
        )}
        <Divider className="mt-5" />
      </div>

      {openUploadPictureModal && (
        <PictureUploadModal
          openModal={openUploadPictureModal}
          setopenModal={setopenUploadPictureModal}
          modalTitle="Upload profile picture"
        />
      )}
      {openUploadDocumentModal && (
        <DocumentUploadModal
          openModal={openUploadDocumentModal}
          setopenModal={setopenUploadDocumentModal}
          modalTitle="Upload KYC documents"
        />
      )}
      {openViewDocumentModal && (
        <ViewDocumentModal
          openModal={openViewDocumentModal}
          setopenModal={setopenViewDocumentModal}
          modalTitle="Document Details"
          selectedDocument={selectedDocument}
        />
      )}
    </div>
  ) : (
    <div>No profile</div>
  );
}

export default UserDetails;
