import React, { useEffect, useState } from 'react'
import FollowersTable from './FollowersTable'
import useApi from '../../../hooks/useApi'
import { useNavigate } from 'react-router-dom';
import { getLoggedInUser } from '../../../helpers/authUtils';
import FollowersFormModal from './FollowersFormModal';
import entitiesApi from '../../../api/entitiesApi';

const columns = [

    { name: "First Name", uid: "first_name" },
    { name: "Last Name", uid: "last_name" },
    { name: "Email", uid: "email" },
    { name: "Phone", uid: "phone" },
    { name: "Gender", uid: "gender" },
    { name: "Date of birth", uid: "date_of_birth" },
    { name: "Actions", uid: "actions" },
];


function FolowersList() {

    const [openFollowerFormModal, setopenFollowerFormModal] = useState(false)
    const navigate = useNavigate()
    const [follower, setFollower] = useState()
    const [followers, setFollowers] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")


    const [user, setUser] = useState()


    useEffect(() => {
        setUser(getLoggedInUser())

    }, [])
    const entitiesActionsApi = useApi(entitiesApi.entitiesAction)
    const getEntityFollowers = async () => {
        setFollowers([])
        await entitiesActionsApi.request({
            "action": "GetEntityFollowers"

        })
    }


    useEffect(() => {

        getEntityFollowers()
    }, [])

    useEffect(() => {
        getEntityFollowers()
    }, [openFollowerFormModal])


    const handleEditAction = (item) => {

        setopenFollowerFormModal(true)

        // setUpdated(false)

        setFollower(item)
        setmodalTitle(`${item.title}`)

    }

    const handleAddAction = () => {


        setopenFollowerFormModal(true)

        setUpdated(false)

        setmodalTitle("Add new department")
        setFollower(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/retailers/departments/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {

        navigate(`/retailers/departments/delete/${item.id}`)
    }


    useEffect(() => {

        if (entitiesActionsApi.data && entitiesActionsApi.data.length) {

            setFollowers(entitiesActionsApi.data)
        }

        console.log('entitiesActionsApi.data', entitiesActionsApi.data)
    }, [entitiesActionsApi.data])

    useEffect(() => {

    }, [openFollowerFormModal])

    //Filtering data
    useEffect(() => {
        setdata(followers)
    }, [followers])


    const handleFilter = (e) => {


        const search_param = e

        if (followers && followers.length > 0 && search_param && search_param !== '') {
            setdata(followers.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(followers);
        }

    };

    return (
        <div>

            {openFollowerFormModal && <FollowersFormModal openEditModal={openFollowerFormModal} setopenEditModal={setopenFollowerFormModal} item={follower} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <FollowersTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default FolowersList