import React, { useState } from 'react'
import { useLocation, useParams } from 'react-router-dom';
import { Divider } from "@heroui/react";

function ProductsDetails() {
    const location = useLocation()

    const [item, setitem] = useState(location.state.item ? location.state.item : null)
    // console.log('category_id', category)
    return (
        <div className="max-w-md mt-10 sm:mt-0">
            <div className="space-y-1">
                <h4 className="text-medium font-medium ">{item ? item.title : ""}</h4>
                <p className="text-small text-default-400">{item && item.description ? item.description : "No description availabe"}</p>
            </div>
            <Divider className="my-4" />
            <div className="flex h-5 items-center space-x-4 text-small">
                {/* <div>Blog</div>
                <Divider orientation="vertical" />
                <div>Docs</div>
                <Divider orientation="vertical" />
                <div>Source</div> */}

                <div className="container flex flex-wrap mx-auto mt-4">
                    <p>Product Images</p>
                    <div className="grid grid-cols-4 gap-2 sm:grid-cols-4 gap-3">
                        {item.images?.map((file) => (
                            <div
                                className="md:shrink-0 rounded "
                                key={file.preview}
                            >

                                <img
                                    className="h-50 w-full object-cover md:h-full md:w-48 shadow-md"
                                    src={file.image}
                                    alt=""
                                />
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
}

export default ProductsDetails
