import React, { useEffect, useState } from 'react'
import AdvertsTable from './AdvertsTable'
import useApi from '../../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import { getLoggedInUser } from '../../../helpers/authUtils';
import AdvertsFormModal from './AdvertsFormModal';

import advertsApi from '../../../api/employees/advertsApi';
import { Loading } from '../../../components';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Description", uid: "description" },
    { name: "Closing Date", uid: "closes" },
    { name: "Vacancies", uid: "vacancies_str" },
    { name: "Actions", uid: "actions" },
];


function AdvertsList() {

    const [openDepartmentFormModal, setopenDepartmentFormModal] = useState(false)
    const navigate = useNavigate()
    const [entity, setEntity] = useState()
    const [adverts, setAdverts] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const advertsActionsApi = useApi(advertsApi.advertsAction)

    const [user, setUser] = useState()


    useEffect(() => {
        setUser(getLoggedInUser())

    }, [])

    const getAdverts = async () => {
        setAdverts([])
        await advertsActionsApi.request({
            "action": "GetAdverts"

        })
    }



    useEffect(() => {

        getAdverts()
    }, [])

    useEffect(() => {
        console.log("")



        getAdverts()



    }, [openDepartmentFormModal])


    const handleEditAction = (item) => {

        setopenDepartmentFormModal(true)

        // setUpdated(false)

        setEntity(item)
        setmodalTitle(`${item.title}`)

    }

    const handleAddAction = () => {


        setopenDepartmentFormModal(true)

        setUpdated(false)

        setmodalTitle("Add new advert")
        setEntity(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/retailers/adverts/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {

        navigate(`/retailers/adverts/delete/${item.id}`)
    }


    useEffect(() => {

        if (advertsActionsApi.data && advertsActionsApi.data.length) {

            setAdverts(advertsActionsApi.data)
        }

        console.log('entitiesActionsApi.data', advertsActionsApi.data)
    }, [advertsActionsApi.data])

    useEffect(() => {

    }, [openDepartmentFormModal])

    //Filtering data
    useEffect(() => {
        setdata(adverts)
    }, [adverts])


    const handleFilter = (e) => {


        const search_param = e

        if (adverts && adverts.length > 0 && search_param && search_param !== '') {
            setdata(adverts.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(adverts);
        }

    };

    return advertsActionsApi.loading ? <Loading loading={advertsActionsApi.loading} /> : (
        <div>

            {openDepartmentFormModal && <AdvertsFormModal openEditModal={openDepartmentFormModal} setopenEditModal={setopenDepartmentFormModal} item={entity} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <AdvertsTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default AdvertsList