import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea, Select, SelectItem } from "@heroui/react";
import { FileUploader, Loading } from '../../components';
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";

import { useDispatch, useSelector } from "react-redux";
import { resetRedux, uploadUserImages } from "../../redux/users/users/actions";
import { getLoggedInUser } from "../../helpers/authUtils";



export default function PictureUploadModal({ openModal, setopenModal, item, updated, setUpdated, modalTitle }) {
    const loading = useSelector((state) => state.Users.loading);
    const response_code = useSelector((state) => state.Users.response_code);
    const response_message = useSelector((state) => state.Users.response_message);
    const errors = useSelector((state) => state.Users.errors);
    const [user, setUser] = useState()
    const dispatch = useDispatch()

    useEffect(() => { setUser(getLoggedInUser()) }, [])
    useEffect(() => {
        dispatch(resetRedux())
    }, [])
    useEffect(() => {

        if (response_code === 0) {
            console.log("response code", response_code)

            // setopenModal(false)
            dispatch(resetRedux())
        }
    }, [response_code])

    const formik = useFormik({
        initialValues: {
            images: [],
        },

        validationSchema: Yup.object({

            images: Yup.array().label('Images'),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log(values)


            let data = new FormData();


            values.images.map((x) => {
                data.append("images", x);
            });

            if (user) {
                dispatch(uploadUserImages(data, user.id))
            }


        },
    });


    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    useEffect(() => {
        if (response_message) {
            toast.success(response_message
            );
        }
    }, [response_message]);


    const handleRemoveSelectedImage = (file) => {
        console.log("file", file);
        // formik.values.images.filter((x) => x.preview !== file.preview);

        formik.setFieldValue(
            "images",
            formik.values.images.filter((x) => x.preview !== file.preview)
        );
    };

    return (
        <>
            <Modal
                isOpen={openModal}
                placement="top"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            {loading ? <Loading /> : <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1 items-center">{modalTitle}</ModalHeader>
                                <ModalBody>



                                    <div className="bg-white">
                                        <FileUploader
                                            placeholder="Select profile pictures"
                                            formik={formik}
                                            name="images"

                                            types=".png,.jpg,.jpeg"
                                            value={formik.values.images}
                                            accept={{
                                                "image/png": [".png"],
                                                "image/jpeg": [".jpeg"],
                                            }}
                                        />
                                        {formik.values.images && formik.values.images.length > 0 && (
                                            <div className="shadow-md rounded my-5 bg-zinc-100 p-5">
                                                <h2 className="text-center font-bold mb-5">
                                                    Images selected for upload
                                                </h2>
                                                <div className="container flex flex-wrap mx-auto">
                                                    <div className="grid grid-cols-4 gap-2 sm:grid-cols-4 gap-3">
                                                        {formik.values.images?.map((file) => (
                                                            <div
                                                                className="md:shrink-0 rounded "
                                                                key={file.preview}
                                                            >
                                                                <button
                                                                    onClick={() => handleRemoveSelectedImage(file)}
                                                                    className="flex  absolute text-red-800 border-red-800 border"
                                                                >
                                                                    x
                                                                </button>
                                                                <img
                                                                    className="h-10 w-full object-cover md:h-full md:w-48 shadow-md"
                                                                    src={file.preview}
                                                                    alt=""
                                                                />
                                                            </div>
                                                        ))}
                                                    </div>
                                                </div>
                                            </div>
                                        )}
                                    </div>


                                </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>}


                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
