import React, { useEffect, useState } from 'react'
import { useLocation, useParams } from 'react-router-dom';
import { Button, Divider, User, image } from "@heroui/react";
import useApi from '../../hooks/useApi';
import { usersAction, usersActionAdmin } from '../../redux/users/users/actions';
import usersApi from '../../api/usersApi';
import { getLoggedInUser } from '../../helpers/authUtils';
import PictureUploadModal from './PictureUploadModal';
import DocumentUploadModal from './DocumentUploadModal';
import ViewDocumentModal from './ViewDocumentModal';
import { useStateContext } from '../../contexts/ContextProvider';
import { ListBoxComponent } from '../../components';
import ImageGallery from "react-image-gallery";

import { imagesTransform } from '../../helpers/utils';



function UserDetails() {


    const [user, setUser] = useState()
    // console.log('category_id', category)

    const usersActionsApi = useApi(usersApi.usersAction)
    // const [profile, setProfile] = useState()

    const { currentColor, profile, setProfile } = useStateContext()

    const [openUploadPictureModal, setopenUploadPictureModal] = useState(false)
    const [openUploadDocumentModal, setopenUploadDocumentModal] = useState(false)
    const [openViewDocumentModal, setopenViewDocumentModal] = useState(false)
    const [selectedDocument, setselectedDocument] = useState()
    const [profileImages, setprofileImages] = useState([])
    const [userDocuments, setuserDocuments] = useState([])

    useEffect(() => {
        getUserProfile()
    }, [])

    const getUserProfile = async () => {
        await usersActionsApi.request({
            "action": "GetUserDetails"
        })
    }


    useEffect(() => {
        console.log('users data', usersActionsApi.data)
        if (usersActionsApi.data) {
            if (usersActionsApi.data.user) {
                setProfile(usersActionsApi.data.user)
            }
        }
    }, [usersActionsApi.data])
    useEffect(() => {
        setUser(getLoggedInUser())
    }, [])
    useEffect(() => {
        getUserProfile()
    }, [])
    useEffect(() => {
        if (usersActionsApi.data) {
            if (usersActionsApi.data.user) {
                setProfile(usersActionsApi.data.user)
            }
        }

        console.log('usersActionsApi.data', usersActionsApi.data)
    }, [usersActionsApi.data])

    const handleSelectDocument = (document) => {
        setopenViewDocumentModal(true)
        setselectedDocument(document)
    }


    useEffect(() => {
        if (profile && profile.images && profile.images.length) {

            setprofileImages(imagesTransform(profile.images))
        }

        if (profile && profile.documents && profile.documents.length) {

            setuserDocuments(imagesTransform(profile.documents))
        }
    }, [profile])


    return profile ? <div className="w-full md:grid-cols-2 gap-x-3 mt-16 sm:mt-0 grid grid-cols-1"  >
        <div><User
            avatarProps={{
                radius: "lg", src: profile.images && profile.images[0] ? profile.images[0].image : null
            }}
            description={profile.email}
            name={`${profile.first_name} ${profile.middle_name ? profile.middle_name : ''} ${profile.last_name}`}
        >
            {profile.email}
        </User>
            <Divider className='mt-5' />
        </div>

        <div className="space-y-3 p-x-2">
            <h4 className="text-medium font-medium ">Gender</h4>
            <p className="text-small text-default-400">{profile && profile.gender ? profile.gender : "No description availabe"}</p>
            <Divider className='mt-5' />
        </div>
        <div className="space-y-3">
            <h4 className="text-medium font-medium ">Date of birth</h4>
            <p className="text-small text-default-400">{profile && profile.date_of_birth ? profile.date_of_birth : "No description availabe"}</p>
            <Divider className='mt-5' />
        </div>
        <div className="space-y-3">
            <h4 className="text-medium font-medium ">Date registered</h4>
            <p className="text-small text-default-400">{profile && profile.created_at ? profile.created_at : "No description availabe"}</p>
            <Divider className='mt-5' />
        </div>
        <div className="space-y-3">
            <h4 className="text-medium font-medium ">Current entity</h4>
            <p className="text-small text-default-400">{profile && profile.entity_title ? profile.entity_title : "No entity details availabe"}</p>
            <Divider className='mt-5' />
        </div>
        <div className="space-y-3">
            <h4 className="text-medium font-medium ">Country</h4>
            <p className="text-small text-default-400">{profile && profile.country_title ? profile.country_title : "No country details availabe"}</p>
            <Divider className='mt-5' />
        </div>
        <div className="space-y-3">
            <h4 className="text-medium font-medium ">Profile verifiction</h4>
            <p className="text-small text-default-400">{profile && profile.is_verified === 'true' ? "Verified" : "Not verified"}</p>
            {profile.is_verified === 'false' && <Button color='primary'>Verify</Button>}
            <Divider className='mt-5' />
        </div>
        <div></div>
        <div className="space-y-3 w-full h-auto">
            <h4 className="text-medium font-medium ">Profile pictures</h4>
            {profile.images && profile.images.length ? <div className=' grid grid-cols-4'>



                <ImageGallery items={profileImages} />;


                {/* {profile.images.map(x => <div className="mb-4">
                    <img
                        style={{
                            width: 100
                        }}
                        src={x.image}
                        className="h-auto max-w-full rounded-lg shadow-md"
                        alt="" />
                </div>)} */}

            </div> : <p className="text-small text-default-400"> No images uploaded</p>}
            {/* <Button color='primary' onPress={() => setopenUploadPictureModal(true)}>Upload pictures</Button> */}
            <Button
                style={{ background: currentColor }}
                onClick={() => setopenUploadPictureModal(true)}
                className="bg-transparent rounded text-white"

                size="lg"
            >
                Upload pictures
            </Button>
            <Divider className='mt-5' />
        </div>

        <div className="space-y-3">
            <h4 className="text-medium font-medium ">KYC Documents</h4>
            {profile.documents && profile.documents.length ? <div className=' grid grid-cols-4'>
                {/*
                {profile.documents.map(x => <div className="mb-4">
                    <img onClick={() => handleSelectDocument(x)} style={{ width: 60 }}
                        src={x.document}
                        className="h-auto min-w-sm w-4 rounded-lg"
                        alt="" />
                </div>)} */}
                <ImageGallery items={userDocuments} />;

            </div> : <p className="text-small text-default-400"> No documents uploaded</p>}
            {/* <Button color='primary' onPress={() => setopenUploadDocumentModal(true)}>Upload documents</Button> */}
            <Button
                style={{ background: currentColor }}
                onClick={() => setopenUploadDocumentModal(true)}
                className="bg-transparent rounded text-white"

                size="lg"
            >
                Upload documents
            </Button>
            <Divider className='mt-5' />
        </div>
        {/* <div className="space-y-1">
            <h4 className="text-medium font-medium ">Your Own Entities</h4>
            {profile && profile.owned_entities.length ? <ListBoxComponent data={profile.owned_entities} /> : <p>No entities yet</p>}

            <Divider className='mt-5' />
        </div>
        <div className="space-y-1">
            <h4 className="text-medium font-medium ">Entities You Are Agent</h4>
            {profile && profile.agency_entities.length ? <ListBoxComponent data={profile.agency_entities} /> : <p>No entities yet</p>}

            <Divider className='mt-5' />
        </div> */}




        {openUploadPictureModal && <PictureUploadModal openModal={openUploadPictureModal} setopenModal={setopenUploadPictureModal} modalTitle="Upload profile picture" />}
        {openUploadDocumentModal && <DocumentUploadModal openModal={openUploadDocumentModal} setopenModal={setopenUploadDocumentModal} modalTitle="Upload KYC documents" />}
        {openViewDocumentModal && <ViewDocumentModal openModal={openViewDocumentModal} setopenModal={setopenViewDocumentModal} modalTitle="Document Details" selectedDocument={selectedDocument} />}
    </div > : <div>No profile</div>
}

export default UserDetails
