import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea } from "@heroui/react";
import { Loading } from '../../components';
import { useFormik } from "formik";
import useApi from "../../hooks/useApi";
import makeAnimated from "react-select/animated"
import CreateSelect from "react-select/creatable";
import { ToastContainer, toast } from "react-toastify";
import clustersApi from "../../api/clustersApi";
import cadresApi from "../../api/cadresApi";


export default function CadresFormModal({ openEditModal, setopenEditModal, item, updated, setUpdated, modalTitle }) {
    // const { isOpen, onOpen, onOpenChange } = useDisclosure();
    const animatedComponent = makeAnimated();
    const [cadre, setCadre] = useState(item ? item : null)

    //Retrieve clusters
    const [clusters, setClusters] = useState([])
    const clustersActionsApi = useApi(clustersApi.clustersAction)
    const getClusters = async () => {
        await clustersActionsApi.request({
            "action": "GetClusters"

        })
    }

    useEffect(() => {
        getClusters()
    }, [])

    useEffect(() => {

        if (clustersActionsApi.data && clustersActionsApi.data.length) {

            setClusters(clustersActionsApi.data.map((i) => ({ label: i.title, value: i.id })))
        }

        console.log
            ('countriesActionsApi.data', clustersActionsApi.data)
    }, [clustersActionsApi.data])



    const [errors, setErrors] = useState();
    const cadresActionsApi = useApi(cadresApi.cadresAction);

    const handleFormulationAction = async (data) => {
        const result = await cadresActionsApi.request(data);

        if (result.ok) {
            setUpdated(true)
            setopenEditModal(setUpdated)
        } else {
            setUpdated(false)
        }

    }

    useEffect(() => { }, [cadre])

    useEffect(() => {

        if (cadresActionsApi.data) {
            if (cadresActionsApi.data.category) {
                setCadre(cadresActionsApi.data.category)
            }
        }
    }, [cadresActionsApi.data])

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    const formik = useFormik({
        initialValues: {
            title: cadre ? cadre.title : '',
            cluster: cadre ? { 'label': cadre.cluster_title, 'value': cadre.cluster } : null,
            description: cadre ? cadre.description : ''
        },

        validationSchema: Yup.object({
            title: Yup.string()
                .min(3, "Must be 15 characters or more")
                .required("Title is required"),
            cluster: Yup.object().required().label('Cluster')
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)
            setErrors([])

            if (item) {

                handleFormulationAction({
                    "action": "UpdateCadre",
                    "cadre_details": {
                        "id": cadre.id,
                        "title": values.title,
                        "cluster": values.cluster.value,
                        "description": values.description ? values.description : '',
                    }
                })
            } else {
                handleFormulationAction({
                    "action": "CreateCadre",
                    "cadre_details": {
                        "title": values.title,
                        "cluster": values.cluster.value,
                        "description": values.description ? values.description : '',
                    }
                })
            }
            // resetForm();
        },
    });


    return (
        <>

            <Modal
                isOpen={openEditModal}
                placement="center"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            {clustersActionsApi.loading ? <Loading /> : <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1">{modalTitle}</ModalHeader>
                                <ModalBody>
                                    <Input
                                        id="title"
                                        name="title"
                                        autoFocus
                                        label="Title"
                                        placeholder="Enter title"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.title}
                                        value={formik.values.title}
                                        color={formik.errors.title ? "danger" : "grey"}
                                        errorMessage={formik.errors.title}
                                    />

                                    <div>
                                        <CreateSelect
                                            styles={{
                                                control: (baseStyles, state) => ({
                                                    ...baseStyles,
                                                    borderColor: state.isFocused ? 'black' : 'grey',
                                                    height: '56px',
                                                    borderRadius: '20px',
                                                }),
                                            }}
                                            id="cluster"
                                            key="cluster"
                                            name="cluster"
                                            components={animatedComponent}
                                            placeholder="Select entity cluster"
                                            isClearable
                                            value={formik.values.cluster}
                                            onChange={(value) => formik.setFieldValue("cluster", value)}
                                            options={clusters}
                                        />
                                        {formik.errors.cluster ? (
                                            <p className="text-red-500 text-sm">{formik.errors.cluster}</p>
                                        ) : null}
                                    </div>

                                    <Textarea
                                        id="description"
                                        key="description"
                                        name="description"
                                        label="Description"
                                        placeholder="Type description"
                                        variant="bordered"
                                        defaultValue={formik.values.description}
                                        value={formik.values.description}
                                        onBlur={formik.handleBlur}
                                        onChange={formik.handleChange}
                                    />
                                </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenEditModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>}


                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
