import React, { useEffect, useState } from 'react'
import CadresTable from './CadresTable'

import useApi from '../../hooks/useApi'
import { useNavigate } from 'react-router-dom';
import CadresFormModal from './CadresFormModal';

import cadresApi from '../../api/cadresApi';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Description", uid: "description" },
    { name: "Actions", uid: "actions" },
];


function CadresList() {
    const [openEditModal, setopenEditModal] = useState(false)

    const navigate = useNavigate()
    const [cadre, setCadre] = useState()
    const [cadres, setCadres] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const cadresActionsApi = useApi(cadresApi.cadresAction)

    const getCadres = async () => {
        await cadresActionsApi.request({
            "action": "GetCadres"

        })
    }
    useEffect(() => {
        setdata(cadres)
    }, [cadres])

    const handleFilter = (e) => {


        const search_param = e

        if (cadres && cadres.length > 0 && search_param && search_param !== '') {
            setdata(cadres.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(cadres);
        }
    };

    useEffect(() => {
        getCadres()
    },[])

    useEffect(() => {
        getCadres()
    }, [openEditModal,getCadres])
    const handleEditAction = (item) => {

        setopenEditModal(true)
        setCadre(item)
        setmodalTitle(`Edit ${item.tittle}`)

    }

    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new cadre")
        setCadre(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/cadres/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/cadres/delete/${item.id}`)
    }



    useEffect(() => {

        if (cadresActionsApi.data && cadresActionsApi.data.length) {

            setCadres(cadresActionsApi.data)
        }
    }, [cadresActionsApi.data])

    useEffect(() => {
        getCadres()
    }, [updated,getCadres])

    return (
        <div className="cadres-list-page rounded-md">
            {openEditModal && <CadresFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} item={cadre} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <CadresTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default CadresList