import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, Input, Textarea } from "@heroui/react";
import { Loading } from '../../components';
import { useFormik } from "formik";
import useApi from "../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import frequenciesApi from "../../api/drugs/frequenciesApi";

export default function FrequenciesFormModal({ openEditModal, setopenEditModal, item, updated, setUpdated, modalTitle }) {
    // const { isOpen, onOpen, onOpenChange } = useDisclosure();

    const [frequency, setFrequency] = useState(item ? item : null)

    const [errors, setErrors] = useState();
    const frequenciesActionsApi = useApi(frequenciesApi.frequenciesAction);

    const handleFrequencyAction = async (data) => {
        const result = await frequenciesActionsApi.request(data);

        if (result.ok) {
            setUpdated(true)
            setopenEditModal(false)
        } else {
            console.log('res', result)
            setErrors(result.data.errors
            )
        }

    }

    useEffect(() => { }, [frequency])

    useEffect(() => {

        if (frequenciesActionsApi.data) {
            if (frequenciesActionsApi.data.category) {
                setFrequency(frequenciesActionsApi.data.category)
            }
        }
    }, [frequenciesActionsApi.data])

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    const formik = useFormik({
        initialValues: {
            title: frequency ? frequency.title : '',
            description: frequency ? frequency.description : '',
            numerical: frequency ? frequency.numerical : '',
            latin: frequency ? frequency.latin : '',
            abbreviation: frequency ? frequency.abbreviation : ''
        },

        validationSchema: Yup.object({
            title: Yup.string()
                .min(3, "Must be 15 characters or more")
                .required("Title is required"),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)
            setErrors([])

            if (item) {

                handleFrequencyAction({
                    "action": "UpdateFrequency",
                    "frequency_details": {
                        "id": frequency.id,
                        "title": values.title,
                        "description": values.description ? values.description : '',
                        "abbreviation": values.abbreviation ? values.abbreviation : '',
                        "latin": values.latin ? values.latin : '',
                        "numerical": values.numerical ? values.numerical : '',
                    }
                })
            } else {
                handleFrequencyAction({
                    "action": "CreateFrequency",
                    "frequency_details": {
                        "title": values.title,
                        "description": values.description ? values.description : '',
                        "abbreviation": values.abbreviation ? values.abbreviation : '',
                        "latin": values.latin ? values.latin : '',
                        "numerical": values.numerical ? values.numerical : '',
                    }
                })
            }




            resetForm();
        },
    });


    return (
        <>

            <Modal
                isOpen={openEditModal}
                placement="center"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            {frequenciesActionsApi.loading ? <Loading /> : <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1">{modalTitle}</ModalHeader>
                                <ModalBody>
                                    <Input
                                        id="title"
                                        name="title"
                                        autoFocus

                                        label="Title"
                                        placeholder="Enter title"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.title}
                                        value={formik.values.title}
                                    />
                                    <Input
                                        id="abbreviation"
                                        name="abbreviation"
                                        autoFocus

                                        label="Abbreviation"
                                        placeholder="Enter abbreviation"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.abbreviation}
                                        value={formik.values.abbreviation}
                                    />
                                    <Input
                                        id="latin"
                                        name="latin"
                                        autoFocus

                                        label="Latin name"
                                        placeholder="Enter latin name"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.latin}
                                        value={formik.values.latin}
                                    />
                                    <Input
                                        id="numerical"
                                        name="numerical"
                                        autoFocus

                                        label="Numeric representation"
                                        placeholder="Enter numerical value"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.numerical}
                                        value={formik.values.numerical}
                                    />

                                    <Textarea
                                        id="description"
                                        key="description"
                                        name="description"
                                        label="Description"
                                        placeholder="Type description"
                                        variant="bordered"
                                        defaultValue={formik.values.description}
                                        value={formik.values.description}
                                        onBlur={formik.handleBlur}
                                        onChange={formik.handleChange}
                                    />
                                </ModalBody>
                                <ModalFooter>
                                    <Button color="danger" variant="flat" onPress={() => setopenEditModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Save
                                    </Button>
                                </ModalFooter>

                            </form>}


                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
