import React, { useEffect, useState } from 'react'
import RoutesTable from './RoutesTable'

import useApi from '../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import RoutesFormModal from './RoutesFormModal';
import bodySystemsApi from '../../api/drugs/bodySystemsApi';
import routesApi from '../../api/drugs/routesApi';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Description", uid: "description" },
    { name: "Actions", uid: "actions" },
];


function RoutesList() {
    const [openEditModal, setopenEditModal] = useState(false)

    const navigate = useNavigate()
    const [route, setRoute] = useState()
    const [routes, setRoutes] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const routesActionsApi = useApi(routesApi.routesAction)

    const getRoutes = async () => {
        await routesActionsApi.request({
            "action": "GetRoutes"

        })
    }

    //Filtering data
    useEffect(() => {
        getRoutes()
    }, [])


    useEffect(() => {
        setdata(routes)
    }, [routes])


    const handleFilter = (e) => {

        console.log('eeeee', e)
        const search_param = e

        if (routes && routes.length > 0 && search_param && search_param !== '') {
            setdata(routes.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(routes);
        }


    };
    const handleEditAction = (item) => {

        setopenEditModal(true)
        setRoute(item)
        setmodalTitle(`Edit ${item.tittle}`)
        // console.log('Item', item)
        // navigate(`/categories/edit/${item.id}`, {
        //     state: {
        //         'item': item
        //     }
        // })
    }

    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new route")
        setRoute(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/routes/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {

        navigate(`/routes/delete/${item.id}`)
    }

    useEffect(() => {
        setdata(routes)
    }, [routes])

    useEffect(() => {

        if (routesActionsApi.data && routesActionsApi.data.length) {

            setRoutes(routesActionsApi.data)
        }
    }, [routesActionsApi.data])

    useEffect(() => {
        getRoutes()
    }, [updated])

    return (
        <div>
            {openEditModal && <RoutesFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} item={route} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <RoutesTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default RoutesList