import React, { useEffect, useState } from 'react'
import CategoriesTable from './CategoriesTable'

import useApi from '../../hooks/useApi'
import categoriesApi from '../../api/categoriesApi'
import { useNavigate, useParams } from 'react-router-dom';
import CategoryFormModal from './CategoryFormModal';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Description", uid: "description" },
    { name: "Actions", uid: "actions" },
];


function CategoriesListHook() {
    const [openEditModal, setopenEditModal] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const navigate = useNavigate()
    const [category, setCategory] = useState()
    const [categories, setCategories] = useState([])
    const [formAction, setformAction] = useState()
    const [data, setdata] = useState()
    const [updated, setUpdated] = useState(false)
    const getAllCategoriesApi = useApi(categoriesApi.categoriesAction)

    const getAllCategories = async () => {
        await getAllCategoriesApi.request({
            "action": "GetAllCategories"

        })
    }
    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new category")
        setformAction('Create')
        setCategory(null)

    }

    useEffect(() => {
        getAllCategories()
    }, [])


    const handleEditAction = (item) => {

        setopenEditModal(true)
        setCategory(item)
        setmodalTitle(`${item.title}`)
        setformAction('Edit')
        // console.log('Item', item)
        // navigate(`/categories/edit/${item.id}`, {
        //     state: {
        //         'item': item
        //     }
        // })
    }
    const handleDetailsAction = (item) => {
        // console.log('Item', item)
        // navigate(`/categories/details/${item.id}`)

        navigate(`/categories/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/categories/delete/${item.id}`)
    }


    useEffect(() => {
        console.log('getAllCategoriesApi.data', getAllCategoriesApi.data)
        if (getAllCategoriesApi.data && getAllCategoriesApi.data.length) {

            setCategories(getAllCategoriesApi.data)
        }
    }, [getAllCategoriesApi.data])

    useEffect(() => {
        getAllCategories()
    }, [updated])


    //Filtering data
    useEffect(() => {
        setdata(categories)
    }, [categories])


    const handleFilter = (e) => {
        const search_param = e
        if (categories && categories.length > 0 && search_param && search_param !== '') {
            setdata(categories.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(categories);
        }

    };

    return (
        <div>
            {openEditModal && <CategoryFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} item={category} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            {data && data.length && <CategoriesTable data={data} columns={columns} editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />}
        </div>
    )
}

export default CategoriesListHook