import React, { useEffect, useState } from 'react'
import BodySystemsTable from './BodySystemsTable'

import useApi from '../../hooks/useApi'
import { useNavigate, useParams } from 'react-router-dom';
import BodySystemFormModal from './BodySystemFormModal';
import bodySystemsApi from '../../api/drugs/bodySystemsApi';
import { Loading } from '../../components';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Description", uid: "description" },
    { name: "Actions", uid: "actions" },
];


function BodySystemsList() {
    const [openEditModal, setopenEditModal] = useState(false)

    const navigate = useNavigate()
    const [bodySystem, setBodySystem] = useState()
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const [bodySystems, setBodySystems] = useState()
    const bodySystemActionsApi = useApi(bodySystemsApi.bodySystemsAction)

    const getAllBodySystems = async () => {
        await bodySystemActionsApi.request({
            "action": "GetBodySystems"

        })
    }

    useEffect(() => {
        getAllBodySystems()
    }, [])

    useEffect(() => {

        if (bodySystemActionsApi.data && bodySystemActionsApi.data.length) {

            setdata(bodySystemActionsApi.data)
        }
    }, [bodySystemActionsApi.data])


    const handleEditAction = (item) => {

        setopenEditModal(true)
        setBodySystem(item)
        setmodalTitle(`${item.title}`)
        // console.log('Item', item)
        // navigate(`/categories/edit/${item.id}`, {
        //     state: {
        //         'item': item
        //     }
        // })
    }

    const handleAddAction = () => {
        setopenEditModal(true)
        setmodalTitle("Add new body system")
        setBodySystem(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/systems/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/systems/delete/${item.id}`)
    }


    useEffect(() => {

        if (bodySystemActionsApi.data && bodySystemActionsApi.data.length) {

            setBodySystems(bodySystemActionsApi.data)
        }
    }, [bodySystemActionsApi.data])

    useEffect(() => {
        getAllBodySystems()
    }, [updated])

    const handleFilter = (e) => {

        console.log('eeeee', e)
        const search_param = e

        if (bodySystems && bodySystems.length > 0 && search_param && search_param !== '') {
            setdata(bodySystems.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(bodySystems);
        }

    };

    return bodySystemActionsApi.loading ? <Loading loading={bodySystemActionsApi.loading} /> : (
        <div>
            {openEditModal && <BodySystemFormModal openEditModal={openEditModal} setopenEditModal={setopenEditModal} item={bodySystem} updated={updated} setUpdated={setUpdated} modalTitle={modalTitle} />}
            <BodySystemsTable data={data} columns={columns}
                editAction={handleEditAction} detailsAction={handleDetailsAction} deleteAction={handleDeleteAction} addAction={handleAddAction} handleFilter={handleFilter} />
        </div>
    )
}

export default BodySystemsList